    def _load_release_png_folder(self, relative_dir, target_dict, label):
        """Carga PNG de un módulo publicado y devuelve cuántos se cargaron."""
        loaded = 0
        folder = Path(resource_path(relative_dir))
        if not folder.exists():
            return loaded
        for file in folder.glob("*.png"):
            try:
                target_dict[file.stem] = tk.PhotoImage(file=str(file))
                loaded += 1
            except Exception as exc:
                print(f"No se pudo cargar imagen {label} {file}: {exc}")
        return loaded

    def load_visual_assets(self):
        """Carga únicamente recursos usados por la edición pública V1.4."""
        self.release_asset_count = 0
        asset_names = {
            "banner": "assets/banner.png",
            "home": "assets/icon_home.png",
            "voices": "assets/icon_voices.png",
            "sliders": "assets/icon_sliders.png",
            "live": "assets/icon_live.png",
            "sound": "assets/icon_sound.png",
            "guide": "assets/icon_guide.png",
            "tray": "assets/icon_tray.png",
            "applause": "assets/icon_applause.png",
            "laugh": "assets/icon_laugh.png",
            "victory": "assets/icon_victory.png",
            "error": "assets/icon_error.png",
            "magic": "assets/icon_magic.png",
        }
        for key, rel in asset_names.items():
            try:
                self.images[key] = tk.PhotoImage(file=resource_path(rel))
                self.release_asset_count += 1
            except Exception as exc:
                print(f"No se pudo cargar imagen {rel}: {exc}")

        try:
            self.root.iconbitmap(resource_path("assets/app_icon.ico"))
        except Exception:
            pass

        # Grupos de imágenes del pack premium.
        self.nav_icons = {}
        self.soundboard_icons = {}
        self.background_images = {}
        self.platform_icons = {}
        self.device_icons = {}
        self.card_images = {}
        self.ui_toggle_images = {}
        self.ui_floating_images = {}
        self.ui_dock_images = {}

        def _cargar_pack(carpeta, destino, prefijo, tam):
            d = Path(resource_path(f"assets/{carpeta}"))
            if not d.exists():
                return
            for file in d.glob("*.png"):
                clave = file.stem.replace(prefijo, "")
                try:
                    if ImageTk is not None and Image is not None and tam:
                        with Image.open(str(file)) as img:
                            destino[clave] = ImageTk.PhotoImage(img.resize(tam))
                    else:
                        destino[clave] = tk.PhotoImage(file=str(file))
                    self.release_asset_count += 1
                except Exception as exc:
                    print(f"No se pudo cargar {file}: {exc}")

        _cargar_pack("pack_nav", self.nav_icons, "nav_", (22, 22))
        _cargar_pack("pack_backgrounds", self.background_images, "background_", None)
        # (pack_soundboard, pack_platform, pack_device y pack_cards no los
        #  muestra ningún widget: no se cargan, para acelerar el arranque.)
        # Pack de UI funcional (toggles, flotante, dock) tipo VoiceMod.
        # Interruptores más grandes: el texto horneado del PNG se lee mejor.
        _cargar_pack("ui_toggles", self.ui_toggle_images, "toggle_", (224, 42))
        _cargar_pack("ui_floating", self.ui_floating_images, "floating_", (64, 64))
        _cargar_pack("ui_dock", self.ui_dock_images, "dock_", (44, 44))

        # Avatares del pack premium (para la voz actual y personajes).
        self.avatar_images = {}
        self.avatar_mini_images = {}   # versión pequeña (44px) para el flotante
        avatars_dir = Path(resource_path("assets/avatars"))
        if avatars_dir.exists():
            for file in avatars_dir.glob("avatar_*.png"):
                clave = file.stem.replace("avatar_", "")
                try:
                    if ImageTk is not None and Image is not None:
                        with Image.open(str(file)) as img:
                            # Recorte cuadrado centrado (busto) para que el
                            # avatar premium llene el marco sin deformarse.
                            w, h = img.size
                            lado = min(w, h)
                            izq = (w - lado) // 2
                            arr = (h - lado) // 3  # algo más arriba: cara centrada
                            recorte = img.crop((izq, arr, izq + lado, arr + lado))
                            self.avatar_images[clave] = ImageTk.PhotoImage(recorte.resize((128, 128)))
                            self.avatar_mini_images[clave] = ImageTk.PhotoImage(recorte.resize((44, 44)))
                    else:
                        self.avatar_images[clave] = tk.PhotoImage(file=str(file))
                    self.release_asset_count += 1
                except Exception as exc:
                    print(f"No se pudo cargar avatar {file}: {exc}")

        # Packs de las pestañas VISIBLES: se cargan ya (los necesita la UI).
        release_folders = [
            ("assets/neon_voicebox_ui", self.neon_ui_images, "interfaz neon"),
            ("assets/voice_characters", self.voice_characters_images, "personajes"),
            ("assets/realistic_effects", self.realistic_fx_images, "efectos"),
            ("assets/real_voice_fx", self.real_voice_fx_images, "voz real"),
            ("assets/asistente_inicial", self.asistente_inicial_images, "configuración"),
            ("assets/streamer", self.streamer_images, "directo"),
            ("assets/test_voz", self.test_voice_images, "test de voz"),
            ("assets/creador_voces", self.creator_images, "creador de voces"),
            ("assets/favoritos_pro", self.favoritos_images, "favoritos"),
            ("assets/grabadora", self.rec_images, "grabadora"),
            ("assets/autotune", self.autotune_images, "autotune"),
            ("assets/cable_virtual", self.cable_images, "cable virtual"),
            ("assets/atajos", self.hotkey_images, "atajos"),
            ("assets/packs", self.pack_images, "packs de voces"),
        ]
        for relative_dir, target, label in release_folders:
            self.release_asset_count += self._load_release_png_folder(relative_dir, target, label)

        # Packs de módulos OCULTOS (no visibles en esta edición): se cargan en
        # segundo plano tras pintar la ventana, para que el arranque sea rápido.
        self._deferred_pack_folders = [
            ("assets/visual_overhaul", self.visual_overhaul_images, "aspecto"),
            ("assets/fx_mixer", self.fx_mixer_images, "mezclador FX"),
            ("assets/fx_designer", self.fx_designer_images, "diseñador FX"),
            ("assets/bilingual_visual", self.bilingual_visual_images, "idioma"),
            ("assets/perfiles", self.profile_images, "perfiles"),
            ("assets/cadena_vocal", self.vocal_chain_images, "cadena vocal"),
            ("assets/mezclador_musical", self.mix_images, "mezclador"),
            ("assets/master_final", self.master_images, "master"),
            ("assets/biblioteca_premium", self.biblioteca_premium_images, "biblioteca"),
            ("assets/portadas_premium", self.portadas_premium_images, "portadas"),
            ("assets/brand_kit", self.brand_kit_images, "marca"),
            ("assets/publicacion_pro", self.publicacion_pro_images, "publicación"),
            ("assets/export_pack", self.export_pack_images, "exportación"),
            ("assets/landing_page", self.landing_page_images, "landing"),
            ("assets/deploy_pro", self.deploy_pro_images, "publicar web"),
        ]

        # Las miniaturas de voces (73) se cargan en la fase diferida
        # (_run_deferred_startup): son el mayor coste y solo las usan la
        # rejilla de favoritos y la vista previa, que se refrescan luego.

    def _load_voice_thumbnails(self):
        """Carga las miniaturas de voces (240x135) usadas en favoritos y en la
        vista previa. Se llama en segundo plano para no frenar el arranque."""
        voices_dir = Path(resource_path("assets/voices"))
        if not (voices_dir.exists() and ImageTk is not None):
            return
        for file in voices_dir.glob("*.png"):
            if file.stem in self.grid_voice_images:
                continue
            try:
                with Image.open(str(file)) as img:
                    thumb = img.resize((240, 135))
                    self.grid_voice_images[file.stem] = ImageTk.PhotoImage(thumb)
                    self.release_asset_count += 1
            except Exception as exc:
                print(f"No se pudo cargar miniatura de voz {file}: {exc}")

    def voice_image_key(self, name):
        text = name.lower()
        replacements = {
            "á":"a","é":"e","í":"i","ó":"o","ú":"u","ü":"u","ñ":"n",
            " ":"_","/":"_","\\":"_","-":"_","·":"_","(":"",")":"",
            ",":"",".":"","¡":"","!":"","?":"","¿":""
        }
        for a, b in replacements.items():
            text = text.replace(a, b)
        while "__" in text:
            text = text.replace("__", "_")
        return text.strip("_")

    def voice_card_image(self, voice_name):
        key = self.voice_image_key(voice_name)
        img = self.grid_voice_images.get(key)
        if img is not None:
            return img
        avatar_key = self.avatar_for_voice(voice_name) if hasattr(self, "avatar_images") else None
        if avatar_key:
            return self.avatar_images.get(avatar_key)
        return None

    def make_card(self, parent, title=None):
        frame = ttk.Frame(parent, style="PremiumCard.TFrame", padding=10)
        if title:
            ttk.Label(frame, text=title, style="Section.TLabel").pack(anchor="w", pady=(0, 8))
        return frame

    SECCION_POR_DEFECTO = "🛠 Herramientas"

    def _setup_pc_scroll_shell(self, parent):
        """Crea un contenedor desplazable general para PC.

        Evita que la app se corte en portátiles o pantallas 1366x768.
        Añade scroll vertical/horizontal y rueda de ratón.
        """
        shell = ttk.Frame(parent)
        shell.pack(fill="both", expand=True)

        canvas = tk.Canvas(shell, bg=COLORS["bg"], highlightthickness=0, bd=0)
        vbar = ttk.Scrollbar(shell, orient="vertical", command=canvas.yview)
        hbar = ttk.Scrollbar(shell, orient="horizontal", command=canvas.xview)
        canvas.configure(yscrollcommand=vbar.set, xscrollcommand=hbar.set)

        canvas.grid(row=0, column=0, sticky="nsew")
        vbar.grid(row=0, column=1, sticky="ns")
        hbar.grid(row=1, column=0, sticky="ew")
        shell.rowconfigure(0, weight=1)
        shell.columnconfigure(0, weight=1)

        inner = ttk.Frame(canvas, padding=10)
        window_id = canvas.create_window((0, 0), window=inner, anchor="nw")

        self._pc_canvas = canvas
        self._pc_canvas_window = window_id
        self._pc_scroll_inner = inner

        def update_scrollregion(_event=None):
            try:
                canvas.configure(scrollregion=canvas.bbox("all"))
            except Exception:
                pass

        def on_canvas_configure(event):
            try:
                # Mantiene la app usable en pantallas pequeñas, pero permite scroll horizontal
                # cuando banners o grids premium pidan más ancho.
                req = max(inner.winfo_reqwidth(), 960)
                canvas.itemconfigure(window_id, width=max(event.width, min(req, 1280)))
                update_scrollregion()
            except Exception:
                pass

        def on_mousewheel(event):
            try:
                # Shift + rueda = desplazamiento horizontal.
                delta = int(-1 * (event.delta / 120)) if getattr(event, "delta", 0) else 0
                if not delta:
                    return
                if getattr(event, "state", 0) & 0x0001:
                    canvas.xview_scroll(delta, "units")
                else:
                    canvas.yview_scroll(delta, "units")
            except Exception:
                pass

        inner.bind("<Configure>", update_scrollregion)
        canvas.bind("<Configure>", on_canvas_configure)
        self.root.bind_all("<MouseWheel>", on_mousewheel)
        self.root.bind_all("<Shift-MouseWheel>", on_mousewheel)
        return inner

    def _aplicar_escala_dpi(self, factor=1.0):
        """Escala de la interfaz proporcional al DPI real de la pantalla."""
        try:
            dpi = float(self.root.winfo_fpixels("1i"))
            self.root.tk.call("tk", "scaling", max(1.0, factor * dpi / 72.0))
        except Exception:
            pass

    def toggle_compact_pc_mode(self):
        """Activa una vista más compacta sin cerrar el programa."""
        try:
            self.root.state("normal")
            self.root.geometry("1120x680")
            self._aplicar_escala_dpi(0.88)
            if hasattr(self, "pc_fix_status"):
                self.pc_fix_status.set("Modo compacto aplicado (proporcional a tu pantalla).")
            self.state.set("Estado: modo compacto PC aplicado")
        except Exception as e:
            messagebox.showerror("Modo compacto", f"No se pudo aplicar el modo compacto:\n{e}")

    def toggle_comfort_pc_mode(self):
        """Vuelve a una vista cómoda para pantallas grandes."""
        try:
            self.root.state("normal")
            self.root.geometry("1280x760")
            self._aplicar_escala_dpi(1.0)
            if hasattr(self, "pc_fix_status"):
                self.pc_fix_status.set("Modo cómodo aplicado (escala real de tu pantalla).")
            self.state.set("Estado: modo cómodo PC aplicado")
        except Exception as e:
            messagebox.showerror("Modo cómodo", f"No se pudo aplicar el modo cómodo:\n{e}")

    def _on_navigation_changed(self, _event=None):
        """Actualiza la ruta visible y evita que la navegación parezca confusa."""
        try:
            section_index = self.notebook.index("current")
            section_name = self.notebook.tab(section_index, "text")
            section_frame = self.notebook.nametowidget(self.notebook.tabs()[section_index])
            sub = next((value for value in self._secciones.values() if value.master is section_frame), None)
            module_name = ""
            if sub is not None and sub.tabs():
                current = sub.index("current")
                module_name = sub.tab(current, "text")
            route = f"{section_name}  ›  {module_name}" if module_name else section_name
            self.current_route.set(route)
            try:
                self.refresh_creator_hub_panels()
            except Exception:
                pass
        except Exception:
            self.current_route.set("VoiceICC")

    def release_quality_audit(self, export=False):
        """Comprueba navegación, pestañas, recursos y archivos clave de la V1.2."""
        approved = {name for name, _label in self.RELEASE_TABS}
        active = []
        missing = []
        empty = []
        duplicate_labels = []
        seen = set()

        for attr, label in self.RELEASE_TABS:
            tab = getattr(self, attr, None)
            if tab is None:
                missing.append(attr)
                continue
            if self._tab_leaf_count(tab) <= 0:
                empty.append(attr)
            key = (self.RELEASE_SECTION_MAP.get(attr, ""), label)
            if key in seen:
                duplicate_labels.append(label)
            seen.add(key)
            active.append(attr)

        unexpected = []
        for _label, tab in self._tab_registry:
            attr = self._tab_attr_name(tab)
            if attr and attr not in approved:
                unexpected.append(attr)

        frozen_release = bool(getattr(sys, "frozen", False))
        if frozen_release:
            # En el .exe instalado los documentos van junto al ejecutable
            # (carpeta {app}), no dentro del bundle de PyInstaller.
            expected_files = [
                "README.md", "GUIA_RAPIDA.md", "PRIVACIDAD.md", "assets/app_icon.png",
            ]
        else:
            expected_files = [
                "README.md", "GUIA_RAPIDA.md",
                "PRIVACIDAD.md", "RELEASE_NOTES.md", "VERSION.txt", "requirements.txt",
                "crear_exe.bat", "crear_instalador_windows.bat",
            ]
        # Un archivo cuenta como presente si está en el bundle o junto al .exe.
        roots = [Path(resource_path("."))]
        try:
            roots.append(Path(sys.executable).resolve().parent)
        except Exception:
            pass
        missing_files = [name for name in expected_files
                         if not any((r / name).exists() for r in roots)]

        critical = len(missing) + len(empty) + len(unexpected) + len(missing_files)
        warnings = len(duplicate_labels) + len(self._release_removed_tabs)
        status = "PASS" if critical == 0 else "REVIEW"
        report = {
            "product": APP_NAME,
            "version": VERSION,
            "generated_at": datetime.now().isoformat(timespec="seconds"),
            "status": status,
            "active_modules": len(active) - len(empty),
            "sections": list(self.RELEASE_SECTIONS),
            "assets_loaded": int(getattr(self, "release_asset_count", 0)),
            "missing_modules": missing,
            "empty_modules": empty,
            "unexpected_modules": unexpected,
            "duplicate_labels": duplicate_labels,
            "missing_release_files": missing_files,
            "runtime_removed_tabs": list(self._release_removed_tabs),
            "packaged_executable": frozen_release,
            "critical_count": critical,
            "warning_count": warnings,
        }
        self.release_audit_last = report
        if status == "PASS":
            self.release_health.set(f"Calidad de version: OK - {report['active_modules']} modulos")
            self.release_status.set(f"VoiceICC {VERSION_TAG} - {report['active_modules']} modulos verificados")
        else:
            self.release_health.set(f"Calidad de version: revisar {critical} punto(s)")
            self.release_status.set(f"VoiceICC {VERSION_TAG} - auditoria pendiente")

        if export:
            folder = Path.home() / "ModuladorVozPremium" / "Informes"
            folder.mkdir(parents=True, exist_ok=True)
            path = folder / f"auditoria_release_{datetime.now().strftime('%Y%m%d_%H%M%S')}.json"
            path.write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")
            messagebox.showinfo("Auditoría V1.4", f"Estado: {status}\n\nInforme guardado en:\n{path}")
        return report

    def open_release_workflow(self):
        """Abre el primer paso del flujo de publicación limpio."""
        self.select_tab(self.tab_asistente_inicial)
        self.state.set("Estado: flujo de publicación iniciado")

    def _crear_seccion(self, nombre):
        if nombre not in self._secciones:
            marco = ttk.Frame(self.notebook)
            self.notebook.add(marco, text=nombre)
            sub = ttk.Notebook(marco, style="VM.Sub.TNotebook")
            sub.pack(fill="both", expand=True)
            self._secciones[nombre] = sub
            self._nombre_seccion[str(sub)] = nombre
            sub.bind("<<NotebookTabChanged>>", self._on_navigation_changed, add="+")
        return self._secciones[nombre]

    def _tab_attr_name(self, tab):
        for attr, value in vars(self).items():
            if attr.startswith("tab_") and value is tab:
                return attr
        return None

    def _parent_for(self, attr):
        if getattr(self, "release_mode", False):
            section = self.RELEASE_SECTION_MAP.get(attr)
            if section:
                return self._crear_seccion(section)
            return self._hidden_tabs_container
        return self._crear_seccion(self._seccion_de.get(attr, self.SECCION_POR_DEFECTO))

    def _add_tab(self, tab, text):
        if getattr(self, "release_mode", False):
            attr = self._tab_attr_name(tab)
            if attr:
                self._release_tab_candidates[attr] = (tab, text)
            return
        tab.master.add(tab, text=text)
        self._tab_registry.append((text, tab))

    def _finalize_release_tabs(self):
        self._tab_registry.clear()
        missing = []
        for attr, release_text in self.RELEASE_TABS:
            candidate = self._release_tab_candidates.get(attr)
            if not candidate:
                missing.append(attr)
                continue
            tab, _old_text = candidate
            try:
                tab.master.add(tab, text=release_text)
                self._tab_registry.append((release_text, tab))
            except Exception:
                missing.append(attr)
        if missing:
            self.release_status.set(f"VoiceICC {VERSION_TAG} · {len(missing)} módulos omitidos")
        else:
            self.release_status.set(f"VoiceICC {VERSION_TAG} · {len(self._tab_registry)} módulos activos")

    def _tab_leaf_count(self, widget):
        try:
            children = widget.winfo_children()
        except Exception:
            return 0
        if not children:
            return 0 if isinstance(widget, (ttk.Frame, tk.Frame)) else 1
        return sum(self._tab_leaf_count(child) for child in children)

    def _prune_empty_release_tabs(self):
        removed = []
        for attr, _label in self.RELEASE_TABS:
            tab = getattr(self, attr, None)
            if tab is None or self._tab_leaf_count(tab) > 0:
                continue
            try:
                tab.master.forget(tab)
                removed.append(attr)
            except Exception:
                pass
        if removed:
            self._release_removed_tabs.extend(removed)
            self._tab_registry = [(text, tab) for text, tab in self._tab_registry if self._tab_attr_name(tab) not in removed]
            self.release_status.set(f"VoiceICC {VERSION_TAG} · {len(self._tab_registry)} módulos activos · vacíos ocultos: {len(removed)}")
        try:
            self.select_tab(self.tab_inicio_premium)
        except Exception:
            pass

    @staticmethod
    def _normalizar(texto):
        tabla = str.maketrans("áéíóúüñÁÉÍÓÚÜÑ", "aeiouunAEIOUUN")
        return str(texto).translate(tabla).lower()

    def search_matches(self, consulta):
        """Coincidencias de la búsqueda global: pestañas y voces."""
        q = self._normalizar(consulta).strip()
        resultados = []
        for texto, tab in self._tab_registry:
            if not q or q in self._normalizar(texto):
                seccion = self._nombre_seccion.get(str(tab.master), "")
                resultados.append((f"{texto}   ·  {seccion}", lambda t=tab: self.select_tab(t)))
        if q:
            for nombre, (categoria, _valores) in VoiceBank.all_presets().items():
                if q in self._normalizar(nombre) or q in self._normalizar(categoria):
                    resultados.append((f"🎙 {nombre}   ·  voz {categoria}", lambda n=nombre: self.apply_pro_voice(n)))
        return resultados[:40]

    def open_search_palette(self):
        """Paleta de búsqueda global (Ctrl+K): pestañas y voces."""
        if getattr(self, "_search_win", None) is not None:
            try:
                self._search_win.lift()
                return
            except Exception:
                self._search_win = None
        win = tk.Toplevel(self.root)
        self._search_win = win
        win.title("Buscar en el modulador")
        win.configure(bg=COLORS["bg"])
        win.geometry("560x420")
        win.transient(self.root)

        marco = ttk.Frame(win, padding=8)
        marco.pack(fill="both", expand=True)
        ttk.Label(marco, text="Escribe para buscar pestañas o voces:", style="Muted.TLabel").pack(anchor="w")
        consulta = tk.StringVar()
        entrada = ttk.Entry(marco, textvariable=consulta, font=("Segoe UI", 13))
        entrada.pack(fill="x", pady=(4, 8))

        lista = tk.Listbox(
            marco,
            bg=COLORS["panel2"],
            fg=COLORS["text"],
            selectbackground=COLORS["accent"],
            relief="flat",
            font=("Segoe UI", 11),
            activestyle="none"
        )
        lista.pack(fill="both", expand=True)
        acciones = []

        def refrescar(*_):
            lista.delete(0, tk.END)
            acciones.clear()
            for texto, accion in self.search_matches(consulta.get()):
                lista.insert(tk.END, "  " + texto)
                acciones.append(accion)
            if acciones:
                lista.selection_set(0)

        def cerrar(*_):
            self._search_win = None
            try:
                win.destroy()
            except Exception:
                pass

        def ejecutar(*_):
            sel = lista.curselection()
            if not sel or sel[0] >= len(acciones):
                return
            accion = acciones[sel[0]]
            cerrar()
            accion()

        def mover(delta):
            sel = lista.curselection()
            idx = (sel[0] if sel else 0) + delta
            idx = max(0, min(lista.size() - 1, idx))
            lista.selection_clear(0, tk.END)
            lista.selection_set(idx)
            lista.see(idx)

        consulta.trace_add("write", refrescar)
        entrada.bind("<Return>", ejecutar)
        entrada.bind("<Down>", lambda e: mover(1))
        entrada.bind("<Up>", lambda e: mover(-1))
        entrada.bind("<Escape>", cerrar)
        lista.bind("<Double-Button-1>", ejecutar)
        lista.bind("<Return>", ejecutar)
        win.protocol("WM_DELETE_WINDOW", cerrar)
        refrescar()
        entrada.focus_set()

    def select_tab(self, tab):
        """Selecciona una pestaña publicada y redirige accesos antiguos a su módulo V1 equivalente."""
        # Si aún quedan módulos ocultos por construir en diferido, los
        # construimos ahora (por si alguno se navega antes de tiempo).
        if not getattr(self, "_deferred_done", True):
            self._run_deferred_startup()
        if getattr(self, "release_mode", False):
            attr = self._tab_attr_name(tab)
            approved = {name for name, _text in self.RELEASE_TABS}
            if attr and attr not in approved:
                redirect_attr = self.RELEASE_REDIRECTS.get(attr, "tab_inicio_premium")
                tab = getattr(self, redirect_attr, getattr(self, "tab_inicio_premium", tab))
        try:
            parent = tab.master
            if isinstance(parent, ttk.Notebook):
                section_frame = parent.master
                if section_frame is not None and section_frame.master == self.notebook:
                    self.notebook.select(section_frame)
                parent.select(tab)
            else:
                self.notebook.select(tab)
        except Exception:
            try:
                self.notebook.select(tab)
            except Exception:
                pass
        try:
            attr = self._tab_attr_name(tab)
            if attr:
                self.track_recent_tab(attr)
        except Exception:
            pass
        try:
            self.root.after_idle(self._on_navigation_changed)
            self.root.after_idle(self.refresh_creator_hub_panels)
        except Exception:
            pass

    def _voiceicc_apply_startup_mode(self):
        try:
            if bool(self.start_minimized.get()) and os.name == "nt":
                self.root.iconify()
                self.vm_ui_status.set("STARTED MINIMIZED")
        except Exception:
            pass

    def voiceicc_startup_command(self):
        """Devuelve el comando de Windows para iniciar VoiceICC."""
        try:
            if getattr(sys, "frozen", False):
                return f'"{sys.executable}"'
            script = Path(__file__).resolve()
            python_exe = Path(sys.executable)
            pythonw = python_exe.with_name("pythonw.exe")
            executable = pythonw if pythonw.exists() else python_exe
            return f'"{executable}" "{script}"'
        except Exception:
            return f'"{sys.executable}"'

    def is_start_with_windows_enabled(self):
        if os.name != "nt" or winreg is None:
            return False
        try:
            key_path = r"Software\Microsoft\Windows\CurrentVersion\Run"
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, key_path, 0, winreg.KEY_READ) as key:
                value, _kind = winreg.QueryValueEx(key, "VoiceICC")
            return bool(value)
        except OSError:
            return False

    def refresh_startup_windows_state(self):
        enabled = self.is_start_with_windows_enabled()
        self.start_with_windows.set(enabled)
        if os.name != "nt":
            self.startup_windows_status.set("Disponible al ejecutar VoiceICC en Windows.")
        elif enabled:
            self.startup_windows_status.set("VoiceICC se iniciará automáticamente con Windows.")
        else:
            self.startup_windows_status.set("Inicio automático desactivado.")
        return enabled

    def voiceicc_toggle_startup_windows(self):
        self.start_with_windows.set(not bool(self.start_with_windows.get()))
        self.set_start_with_windows(enabled=bool(self.start_with_windows.get()), show_message=False)

    def set_start_with_windows(self, enabled=None, show_message=True):
        if enabled is None:
            enabled = bool(self.start_with_windows.get())
        if os.name != "nt" or winreg is None:
            self.start_with_windows.set(False)
            self.startup_windows_status.set("Esta función solo puede configurarse desde Windows.")
            if show_message:
                messagebox.showinfo("VoiceICC", "La opción de inicio automático se configura al ejecutar la app en Windows.")
            return False
        try:
            key_path = r"Software\Microsoft\Windows\CurrentVersion\Run"
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, key_path, 0, winreg.KEY_SET_VALUE) as key:
                if enabled:
                    winreg.SetValueEx(key, "VoiceICC", 0, winreg.REG_SZ, self.voiceicc_startup_command())
                else:
                    try:
                        winreg.DeleteValue(key, "VoiceICC")
                    except FileNotFoundError:
                        pass
            self.start_with_windows.set(bool(enabled))
            self.refresh_startup_windows_state()
            try:
                self.save_config(silent=True)
            except Exception:
                pass
            if show_message:
                messagebox.showinfo(
                    "VoiceICC",
                    "VoiceICC arrancará con Windows." if enabled else "VoiceICC ya no arrancará con Windows."
                )
            return True
        except Exception as exc:
            self.startup_windows_status.set(f"No se pudo cambiar el inicio automático: {exc}")
            self.start_with_windows.set(self.is_start_with_windows_enabled())
            if show_message:
                messagebox.showerror("VoiceICC", f"No se pudo guardar la opción de Windows:\n{exc}")
            return False

    def open_voiceicc_brand_folder(self):
        folder = Path(resource_path("assets/voiceicc_brand"))
        try:
            if os.name == "nt":
                os.startfile(folder)
            elif sys.platform == "darwin":
                subprocess.Popen(["open", str(folder)])
            else:
                subprocess.Popen(["xdg-open", str(folder)])
        except Exception:
            messagebox.showinfo("VoiceICC Brand Kit", str(folder))

    def vm_sidebar_items(self):
        return [
            ("🏠", "Inicio", "Home", "🏠 Inicio", "home"),
            ("◈", "VOICEBOX", "VOICEBOX", "🎙 Voces", "voicebox"),
            ("▦", "SOUNDBOARD", "SOUNDBOARD", "🎛 Efectos", "soundboard"),
            ("◉", "VOICELAB", "VOICELAB", "🎵 Studio", "lab"),
            ("⚙", "Ajustes", "Settings", "⚙ Ajustes", "settings"),
        ]

    def vm_build_sidebar_buttons(self):
        if not hasattr(self, "vm_sidebar_nav"):
            return
        for child in self.vm_sidebar_nav.winfo_children():
            child.destroy()
        self.vm_sidebar_buttons.clear()
        lang = self.app_language.get() if hasattr(self, "app_language") else "Español"
        collapsed = bool(self.vm_sidebar_collapsed.get()) if hasattr(self, "vm_sidebar_collapsed") else False
        for item in self.vm_sidebar_items():
            icon, es, en, section = item[0], item[1], item[2], item[3]
            navkey = item[4] if len(item) > 4 else None
            label = es if lang == "Español" else en
            img = self.nav_icons.get(navkey) if navkey else None
            btn = tk.Button(
                self.vm_sidebar_nav,
                text=("" if collapsed else f"   {label}") if img else (f"  {icon}" if collapsed else f"  {icon}   {label}"),
                image=img if img else "",
                compound="left" if (img and not collapsed) else "center",
                anchor="w" if not collapsed else "center",
                bg="#111117",
                fg="#a9a9b7",
                activebackground="#23232d",
                activeforeground="#ffffff",
                relief="flat",
                bd=0,
                padx=12 if not collapsed else 6,
                pady=10,
                font=("Segoe UI", 10, "bold"),
                cursor="hand2",
                command=lambda name=section: self.vm_select_section(name),
            )
            if img:
                btn.image = img
            btn.pack(fill="x", padx=9, pady=2)
            self.vm_sidebar_buttons[section] = btn
        self.vm_refresh_sidebar()

    def vm_toggle_sidebar(self):
        try:
            collapsed = not bool(self.vm_sidebar_collapsed.get())
            self.vm_sidebar_collapsed.set(collapsed)
            if hasattr(self, "vm_sidebar"):
                self.vm_sidebar.configure(width=76 if collapsed else 205)
            if hasattr(self, "vm_logo_text"):
                self.vm_logo_text.configure(text="VN" if collapsed else "VoiceICC")
            if hasattr(self, "vm_search_hint_button"):
                self.vm_search_hint_button.configure(text="⌨" if collapsed else "⌨  Ctrl+K  Search")
            if hasattr(self, "vm_sidebar_footer_label"):
                self.vm_sidebar_footer_label.configure(wraplength=54 if collapsed else 175, justify="center" if collapsed else "left")
            self.vm_build_sidebar_buttons()
            try:
                self.save_config(silent=True)
            except Exception:
                pass
        except Exception as exc:
            self.vm_ui_status.set(f"UI ERROR · {exc}")

    def vm_select_section(self, section_name):
        try:
            sub = self._secciones.get(section_name)
            if sub is None:
                return
            self.notebook.select(sub.master)
            if sub.tabs():
                sub.select(0)
            self.vm_refresh_sidebar(section_name)
            self._on_navigation_changed()
        except Exception as exc:
            self.vm_ui_status.set(f"NAV ERROR · {exc}")

    def vm_refresh_sidebar(self, active_section=None):
        if not getattr(self, "vm_sidebar_buttons", None):
            return
        if active_section is None:
            try:
                index = self.notebook.index("current")
                active_section = self.notebook.tab(index, "text")
            except Exception:
                active_section = "🏠 Inicio"
        for section, btn in self.vm_sidebar_buttons.items():
            selected = section == active_section
            try:
                btn.configure(
                    bg="#252532" if selected else "#111117",
                    fg="#ffffff" if selected else "#a9a9b7",
                    highlightbackground="#8c52ff" if selected else "#111117",
                    highlightthickness=2 if selected else 0,
                )
            except Exception:
                pass

    def vm_search_submit(self, _event=None):
        query = self.vm_search_var.get().strip()
        if query == getattr(self, "_search_placeholder", None):
            query = ""
        if not query:
            self.open_search_palette()
            return
        results = self.search_matches(query)
        if results:
            results[0][1]()
            self.vm_ui_status.set(f"FOUND · {results[0][0].split('·')[0].strip()}")
        else:
            self.vm_ui_status.set("NO RESULTS")
            self.open_search_palette()

    def vm_toggle_voice_engine(self):
        desired = bool(self.vm_voice_changer_enabled.get())
        if desired:
            ok = self.start(silent=False)
            if not ok:
                self.vm_voice_changer_enabled.set(False)
                self.vm_ui_status.set("VOICE OFF")
                return
            self.vm_ui_status.set("VOICE ON")
        else:
            self.stop()
            self.vm_ui_status.set("VOICE OFF")

    def vm_toggle_background_fx(self):
        enabled = bool(self.vm_background_fx_enabled.get())
        try:
            with self.engine.lock:
                self.engine.sfx_volume = 0.65 if enabled else 0.0
            self.vm_ui_status.set("FX ON" if enabled else "FX OFF")
        except Exception:
            pass

    def vm_stop_all(self):
        try:
            self.stop_sfx()
        except Exception:
            pass
        try:
            self.karaoke_stop()
        except Exception:
            pass
        try:
            with self.engine.lock:
                self.engine.sfx_buffer = np.zeros(0, dtype=np.float32)
        except Exception:
            pass
        try:
            self.stop()
        except Exception:
            pass
        self.vm_voice_changer_enabled.set(False)
        self.mute.set(False)
        self.update_engine()
        self.vm_refresh_power()
        self.vm_ui_status.set("ALL STOPPED")
        self.state.set("Estado: todo detenido")

    def toggle_voiceicc_right_rail(self):
        try:
            visible = not bool(self.voiceicc_right_rail_visible.get())
            self.voiceicc_right_rail_visible.set(visible)
            if hasattr(self, "voiceicc_right_rail"):
                if visible:
                    self.voiceicc_right_rail.pack(side="right", fill="y", padx=(8, 0))
                else:
                    self.voiceicc_right_rail.pack_forget()
            self.save_config(silent=True)
        except Exception as exc:
            self.vm_ui_status.set(f"PANEL ERROR · {exc}")

    def experience_checklist_items(self):
        return [
            ("mic", "Micrófono seleccionado", bool(self.input_dev.get()), lambda: self.select_tab(self.tab_ajustes)),
            ("out", "Salida seleccionada", bool(self.output_dev.get()), lambda: self.select_tab(self.tab_ajustes)),
            ("voice", "Voz elegida", bool(self.voiceicc_current_voice_name.get()), lambda: self.select_tab(self.tab_voice_characters)),
            ("test", "Test de voz realizado", bool(getattr(self, "experience_test_done", False)), lambda: self.select_tab(self.tab_test_voz)),
            ("startup", "Inicio con Windows", bool(self.start_with_windows.get()), lambda: self.voiceicc_toggle_startup_windows()),
        ]

    def experience_refresh_checklist(self):
        try:
            items=self.experience_checklist_items()
            done=sum(1 for _k,_t,state,_a in items if state)
            self.experience_checklist_text.set(f"{done} de {len(items)} pasos completados")
            self.experience_tip_text.set("VoiceICC está listo para usar." if done==len(items) else "Completa los pasos pendientes para dejar VoiceICC preparado.")
            if hasattr(self,"experience_checklist_frame"):
                for child in self.experience_checklist_frame.winfo_children(): child.destroy()
                for key,title,state,action in items:
                    row=tk.Frame(self.experience_checklist_frame,bg="#121726")
                    row.pack(fill="x",pady=2)
                    tk.Label(row,text="✓" if state else "○",bg="#121726",fg="#62ffb4" if state else "#66708a",font=("Segoe UI",10,"bold"),width=2).pack(side="left")
                    tk.Label(row,text=title,bg="#121726",fg="#ffffff" if state else "#aab3ca",font=("Segoe UI",8),anchor="w").pack(side="left",fill="x",expand=True)
                    if not state:
                        tk.Button(row,text="Abrir",command=action,bg="#201a35",fg="#cdbbff",activebackground="#7c3cff",activeforeground="#ffffff",relief="flat",bd=0,padx=7,pady=3,font=("Segoe UI",7,"bold")).pack(side="right")
            if hasattr(self,"experience_progress_bar"):
                self.experience_progress_bar["value"]=int(done/len(items)*100)
        except Exception:
            pass

    def experience_mark_test_done(self):
        self.experience_test_done=True
        self.experience_refresh_checklist()

    def experience_open_onboarding(self):
        try:
            if getattr(self,"_experience_win",None) is not None and self._experience_win.winfo_exists():
                self._experience_win.lift(); return
        except Exception:
            pass
        win=tk.Toplevel(self.root)
        self._experience_win=win
        win.title("Bienvenido a VoiceICC")
        win.configure(bg="#090d16")
        win.geometry("760x520")
        win.transient(self.root)
        win.grab_set()
        header=tk.Frame(win,bg="#111725")
        header.pack(fill="x")
        tk.Label(header,text="VOICEICC EXPERIENCE",bg="#111725",fg="#ffffff",font=("Segoe UI",22,"bold")).pack(anchor="w",padx=24,pady=(20,2))
        tk.Label(header,text="Tu voz. Tu identidad. Configura todo en unos pasos.",bg="#111725",fg="#97a3c0",font=("Segoe UI",10)).pack(anchor="w",padx=24,pady=(0,18))
        body=tk.Frame(win,bg="#090d16")
        body.pack(fill="both",expand=True,padx=22,pady=18)
        steps=[
            ("1","Selecciona micrófono y salida", "Abre Ajustes y elige tus dispositivos.", lambda:self.select_tab(self.tab_ajustes)),
            ("2","Elige tu personaje de voz", "Prueba una voz natural o una voz creativa.", lambda:self.select_tab(self.tab_voice_characters)),
            ("3","Haz una prueba rápida", "Comprueba volumen, latencia y claridad.", lambda:self.select_tab(self.tab_test_voz)),
            ("4","Configura Windows", "Activa inicio automático si lo necesitas.", lambda:self.voiceicc_toggle_startup_windows()),
        ]
        for i,(num,title,sub,cmd) in enumerate(steps):
            card=tk.Frame(body,bg="#121726",highlightbackground="#2a3552",highlightthickness=1)
            card.grid(row=i//2,column=i%2,sticky="nsew",padx=6,pady=6)
            tk.Label(card,text=num,bg="#7c3cff",fg="#ffffff",font=("Segoe UI",12,"bold"),width=3,pady=6).pack(anchor="w",padx=12,pady=(12,8))
            tk.Label(card,text=title,bg="#121726",fg="#ffffff",font=("Segoe UI",11,"bold"),wraplength=280,justify="left").pack(anchor="w",padx=12)
            tk.Label(card,text=sub,bg="#121726",fg="#9ba6bf",font=("Segoe UI",8),wraplength=280,justify="left").pack(anchor="w",padx=12,pady=(4,10))
            tk.Button(card,text="Abrir",command=lambda c=cmd:(c(),win.destroy()),bg="#201a35",fg="#d7c8ff",activebackground="#7c3cff",activeforeground="#ffffff",relief="flat",bd=0,pady=6,font=("Segoe UI",8,"bold")).pack(fill="x",padx=12,pady=(0,12))
            body.columnconfigure(i%2,weight=1); body.rowconfigure(i//2,weight=1)
        footer=tk.Frame(win,bg="#090d16")
        footer.pack(fill="x",padx=22,pady=(0,18))
        def finish():
            self.experience_onboarding_completed.set(True)
            try:self.save_config(silent=True)
            except Exception:pass
            win.destroy(); self.experience_refresh_checklist()
        tk.Button(footer,text="COMPLETAR MÁS TARDE",command=win.destroy,bg="#1a2030",fg="#aeb8cf",relief="flat",bd=0,padx=14,pady=8,font=("Segoe UI",8,"bold")).pack(side="left")
        tk.Button(footer,text="EMPEZAR CON VOICEICC",command=finish,bg="#8c52ff",fg="#ffffff",activebackground="#ff4fa3",activeforeground="#ffffff",relief="flat",bd=0,padx=18,pady=8,font=("Segoe UI",8,"bold")).pack(side="right")

    def voiceicc_open_feature(self, tab_attr):
        tab = getattr(self, tab_attr, None)
        if tab is not None:
            self.select_tab(tab)

    def voiceicc_apply_featured_voice(self, name):
        try:
            self.select_voice_character(name)
            self.voiceicc_dashboard_status.set(f"Voz activa: {name} - Perfil aplicado")
            self.voiceicc_current_voice_name.set(name)
            try:
                item = next((x for x in self.voice_characters_data() if x.get("name") == name), None)
                if item:
                    self.voiceicc_current_voice_role.set(f"{item.get('role_es', 'Voz premium')} - {item.get('age', 'Natural')}")
                    if hasattr(self, "voiceicc_current_voice_image_label"):
                        key = item.get("image", "")
                        neon_key = f"voice_{key}"
                        avatar_key = item.get("avatar", "")
                        if neon_key in self.neon_ui_images:
                            self.voiceicc_current_voice_image_label.configure(image=self.neon_ui_images[neon_key])
                            self.voiceicc_current_voice_image_label.image = self.neon_ui_images[neon_key]
                        elif key in self.voice_characters_images:
                            self.voiceicc_current_voice_image_label.configure(image=self.voice_characters_images[key])
                            self.voiceicc_current_voice_image_label.image = self.voice_characters_images[key]
                        elif avatar_key in self.avatar_images:
                            self.voiceicc_current_voice_image_label.configure(image=self.avatar_images[avatar_key])
                            self.voiceicc_current_voice_image_label.image = self.avatar_images[avatar_key]
            except Exception:
                pass
            if hasattr(self, "voiceicc_current_voice_label"):
                self.voiceicc_current_voice_label.configure(text=name)
            self.voiceicc_refresh_selected_voice_cards(name)
            if hasattr(self, "voiceicc_rail_voice_name"):
                self.voiceicc_rail_voice_name.configure(text=name)
            if hasattr(self, "voiceicc_rail_voice_role"):
                self.voiceicc_rail_voice_role.configure(text=self.voiceicc_current_voice_role.get())
            self.voiceicc_update_setup_progress()
            self.experience_refresh_checklist()
        except Exception as exc:
            self.voiceicc_dashboard_status.set(f"No se pudo aplicar {name}: {exc}")

    def voiceicc_refresh_selected_voice_cards(self, selected_name=None):
        selected_name = selected_name or self.voiceicc_current_voice_name.get()
        for name, card in getattr(self, "voiceicc_featured_cards", {}).items():
            try:
                active = name == selected_name
                card.configure(
                    highlightbackground="#a65cff" if active else "#20283b",
                    highlightthickness=2 if active else 1,
                    bg="#17152a" if active else "#0d121e",
                )
            except Exception:
                pass

    def voiceicc_update_setup_progress(self):
        score = 35
        try:
            if self.input_dev.get(): score += 18
            if self.output_dev.get(): score += 18
            if self.voiceicc_current_voice_name.get(): score += 12
            if bool(self.start_with_windows.get()): score += 9
            if bool(self.vm_voice_changer_enabled.get()): score += 8
        except Exception:
            score = 72
        score = max(0, min(100, score))
        self.voiceicc_setup_progress.set(score)
        self.voiceicc_setup_text.set(f"Configuracion VoiceICC - {score}%")
        if hasattr(self, "voiceicc_setup_bar"):
            self.voiceicc_setup_bar["value"] = score

    def voiceicc_animate_waveform(self):
        try:
            canvas = getattr(self, "voiceicc_wave_canvas", None)
            if canvas is None or not canvas.winfo_exists():
                return
            w = max(280, canvas.winfo_width())
            h = max(38, canvas.winfo_height())
            canvas.delete("wave")
            phase = self.voiceicc_wave_phase
            level = max(0.12, min(1.0, float(getattr(self.engine, "out_level", 0.18)) * 4.5)) if hasattr(self, "engine") else 0.35
            points=[]
            for x in range(0,w+1,5):
                t=x/max(1,w)
                envelope=math.sin(math.pi*t)**0.65
                y=h/2 + math.sin(t*math.pi*10+phase)*h*0.24*envelope*level + math.sin(t*math.pi*23-phase*0.7)*h*0.08*envelope
                points.extend((x,y))
            canvas.create_line(*points, fill="#00dff5", width=2, smooth=True, tags="wave")
            points2=[]
            for x in range(0,w+1,6):
                t=x/max(1,w)
                envelope=math.sin(math.pi*t)**0.7
                y=h/2 + math.sin(t*math.pi*8-phase*0.8)*h*0.18*envelope*level
                points2.extend((x,y))
            canvas.create_line(*points2, fill="#a65cff", width=2, smooth=True, tags="wave")
            self.voiceicc_wave_phase=(phase+0.22)%(math.pi*2)
            self.root.after(60,self.voiceicc_animate_waveform)
        except Exception:
            try:self.root.after(120,self.voiceicc_animate_waveform)
            except Exception:pass

    def voiceicc_open_pro_panel(self):
        try:
            self.select_tab(self.tab_publicacion_pro)
            self.vm_ui_status.set("VOICEICC PRO · COMMERCIAL")
        except Exception:
            pass

    def voiceicc_refresh_dashboard_metrics(self):
        try:
            # Valores visuales conservadores; los medidores de audio reales siguen en sus módulos.
            mic = int(min(100, max(0, getattr(self.engine, "input_level", 0.18) * 100))) if hasattr(self, "engine") else 18
            out = int(min(100, max(0, getattr(self.engine, "output_level", 0.12) * 100))) if hasattr(self, "engine") else 12
            self.voiceicc_cpu_text.set(f"CPU {8 + (mic % 9)}%")
            self.voiceicc_ram_text.set(f"RAM {24 + (out % 11)}%")
            latency_map = {"Ultra baja": "5.8 ms", "Baja": "8.3 ms", "Estable": "12.6 ms", "Máxima estabilidad": "20.4 ms"}
            self.voiceicc_latency_text.set(f"LATENCIA {latency_map.get(self.latency.get(), '8.3 ms')}")
            self.voiceicc_quality_text.set("ÓPTIMA" if not self.mute.get() else "SILENCIADA")
            self.voiceicc_update_setup_progress()
            for bar_name, value in (("voiceicc_cpu_bar", 12), ("voiceicc_ram_bar", 28), ("voiceicc_latency_bar", 20), ("voiceicc_quality_bar", 92)):
                if hasattr(self, bar_name):
                    getattr(self, bar_name)["value"] = value
            self.root.after(1400, self.voiceicc_refresh_dashboard_metrics)
        except Exception:
            try:self.root.after(1800, self.voiceicc_refresh_dashboard_metrics)
            except Exception:pass

    def apply_workspace_mode(self, mode=None, show_message=False):
        try:
            if mode:
                self.workspace_density.set(mode)
            mode = self.workspace_density.get()
            settings = {
                "Compacto": {"sidebar": 76, "rail": 260, "top": 58, "pad": 5},
                "Equilibrado": {"sidebar": 205, "rail": 315, "top": 70, "pad": 8},
                "Showroom": {"sidebar": 220, "rail": 350, "top": 82, "pad": 12},
            }.get(mode, {"sidebar": 205, "rail": 315, "top": 70, "pad": 8})
            if hasattr(self, "vm_sidebar"):
                collapsed = bool(self.vm_sidebar_collapsed.get())
                self.vm_sidebar.configure(width=76 if collapsed else settings["sidebar"])
            if hasattr(self, "voiceicc_right_rail"):
                self.voiceicc_right_rail.configure(width=settings["rail"])
            if hasattr(self, "voiceicc_topbar"):
                self.voiceicc_topbar.configure(height=settings["top"])
            self.workspace_status.set(f"Modo {mode} aplicado · interfaz optimizada para PC")
            try:
                self.save_config(silent=True)
            except Exception:
                pass
            if show_message:
                messagebox.showinfo("VoiceICC Workspace", f"Modo visual aplicado: {mode}")
        except Exception as exc:
            self.workspace_status.set(f"No se pudo aplicar el modo: {exc}")

    def toggle_workspace_focus(self):
        try:
            enabled = bool(self.workspace_focus_mode.get())
            if hasattr(self, "voiceicc_right_rail"):
                if enabled:
                    self.voiceicc_right_rail.pack_forget()
                elif self.voiceicc_right_rail_visible.get():
                    self.voiceicc_right_rail.pack(side="right", fill="y", padx=(8, 0))
            if hasattr(self, "vm_sidebar"):
                self.vm_sidebar.configure(width=76 if enabled else (76 if self.vm_sidebar_collapsed.get() else 205))
            self.workspace_status.set("Focus activo · paneles secundarios ocultos" if enabled else "Focus desactivado · workspace completo")
            try:
                self.save_config(silent=True)
            except Exception:
                pass
        except Exception as exc:
            self.workspace_status.set(f"Error Focus: {exc}")

    def refresh_workspace_notifications(self):
        notes = []
        try:
            if not self.input_dev.get():
                notes.append("Selecciona micrófono")
            if not self.output_dev.get():
                notes.append("Selecciona salida")
            if not self.preset.get():
                notes.append("Selecciona una voz")
            if not bool(self.start_with_windows.get()):
                notes.append("Inicio con Windows desactivado")
        except Exception:
            pass
        self.workspace_notifications.set(" · ".join(notes) if notes else "Todo preparado para usar VoiceICC")

    def build_workspace_control_bar(self, parent):
        bar = tk.Frame(parent, bg="#12131b", highlightbackground="#2b2d3c", highlightthickness=1)
        tk.Label(bar, text="WORKSPACE", bg="#12131b", fg="#8f91a5", font=("Segoe UI", 9, "bold")).pack(side="left", padx=(10, 6))
        for mode in ("Compacto", "Equilibrado", "Showroom"):
            tk.Button(bar, text=mode.upper(), command=lambda m=mode: self.apply_workspace_mode(m), bg="#1d1f2b", fg="#dfe2ff", activebackground="#7c5cff", activeforeground="#ffffff", relief="flat", bd=0, padx=9, pady=5, font=("Segoe UI", 9, "bold"), cursor="hand2").pack(side="left", padx=2, pady=5)
        tk.Checkbutton(bar, text="FOCUS", variable=self.workspace_focus_mode, command=self.toggle_workspace_focus, indicatoron=False, bg="#251c36", fg="#ffffff", selectcolor="#8c52ff", activebackground="#382650", activeforeground="#ffffff", relief="flat", bd=0, padx=10, pady=5, font=("Segoe UI", 9, "bold"), cursor="hand2").pack(side="right", padx=6, pady=5)
        tk.Label(bar, textvariable=self.workspace_notifications, bg="#12131b", fg="#00e5ff", font=("Segoe UI", 9), anchor="e").pack(side="right", fill="x", expand=True, padx=8)
        return bar

    def _monitor_device(self):
        """Salida para escucharte: la predeterminada de Windows."""
        try:
            dev = sd.default.device[1]
            if dev is not None and int(dev) >= 0:
                return int(dev)
        except Exception:
            pass
        return None

    def toggle_voice_normal(self):
        """Alterna entre voz modulada (efectos ON) y voz normal (limpia)."""
        self.effects_enabled.set(not bool(self.effects_enabled.get()))
        self.update_engine()
        self._float_refresh()
        if bool(self.effects_enabled.get()):
            self.state.set("Estado: 🎭 voz modulada")
        else:
            self.state.set("Estado: 🙂 voz normal (sin efectos)")

    def panic_reset(self):
        """Modo pánico: si algo suena mal en directo, vuelve todo a voz
        limpia al instante (sin efectos, sin silenciar, sin monitor)."""
        self.effects_enabled.set(True)
        self.mute.set(False)
        limpia = "Voz clara" if "Voz clara" in VoiceBank.all_presets() else "Gaming limpio"
        self.apply_pro_voice(limpia)
        try:
            self.engine.stop_monitor()
            if hasattr(self, "monitor_var"):
                self.monitor_var.set(False)
        except Exception:
            pass
        self.update_engine()
        self.state.set("Estado: 🆘 pánico · voz limpia restaurada")

    def _bind_ptt_key(self):
        """Engancha la tecla push-to-talk global (configurable)."""
        if not GLOBAL_HOTKEYS_AVAILABLE:
            return
        for h in getattr(self, "_ptt_hooks", []):
            try:
                global_keyboard.unhook_key(h)
            except Exception:
                pass
        self._ptt_hooks = []
        tecla = (self.ptt_key.get() or "v").strip().lower()
        try:
            self._ptt_hooks.append(global_keyboard.on_press_key(tecla, lambda e: self.root.after(0, self.push_to_talk_press)))
            self._ptt_hooks.append(global_keyboard.on_release_key(tecla, lambda e: self.root.after(0, self.push_to_talk_release)))
        except Exception as e:
            print("No se pudo enganchar la tecla PTT:", e)

    def rebind_ptt_key(self):
        """Reengancha la tecla PTT cuando el usuario la cambia en Ajustes."""
        self._bind_ptt_key()
        self.state.set(f"Estado: push-to-talk asignado a la tecla '{self.ptt_key.get().upper()}'")

    def push_to_talk_press(self):
        """Mantener pulsado: hablar (quita el silencio)."""
        if bool(self.ptt_mode.get()):
            self.mute.set(False)
            self.update_engine()

    def push_to_talk_release(self):
        """Soltar: silencio (modo push-to-talk)."""
        if bool(self.ptt_mode.get()):
            self.mute.set(True)
            self.update_engine()

    def toggle_ptt_mode(self):
        """Activa/desactiva push-to-talk. Al activar, empieza en silencio."""
        activo = bool(self.ptt_mode.get())
        self.mute.set(activo)  # en PTT arranca callado hasta pulsar
        self.update_engine()
        self.state.set("Estado: 🎙 push-to-talk ON (mantén la tecla)" if activo else "Estado: push-to-talk OFF")

    def toggle_previous_voice(self):
        """Alterna entre la voz actual y la anterior (Ctrl+Shift+X)."""
        anterior = getattr(self, "_voz_anterior", None)
        if not anterior or anterior not in VoiceBank.all_presets():
            self.state.set("Estado: aún no hay voz anterior a la que volver")
            return
        self.apply_pro_voice(anterior)
        self.state.set(f"Estado: ↔ voz anterior · {anterior}")

    def toggle_monitor(self):
        if not self.monitor_var.get():
            self.engine.stop_monitor()
            self.state.set("Estado: monitor apagado")
            return
        if not self.engine.running:
            self.monitor_var.set(False)
            self._device_test_report("Para escucharte, primero enciende el directo con ⏻.")
            return
        if self.engine.start_monitor(self._monitor_device()):
            self.state.set("Estado: 🎧 te escuchas por la salida predeterminada de Windows")
        else:
            self.monitor_var.set(False)
            self._device_test_report("No se pudo abrir el monitor en la salida predeterminada. ¿Auriculares conectados?")

    def toggle_float_panel(self):
        """Botón flotante siempre visible: enciende/para el modulador
        sin buscar la ventana (ideal encima del juego)."""
        if getattr(self, "_float_win", None) is not None:
            try:
                self._float_win.destroy()
            except Exception:
                pass
            self._float_win = None
            return
        win = tk.Toplevel(self.root)
        self._float_win = win
        win.overrideredirect(True)
        try:
            win.attributes("-topmost", True)
        except Exception:
            pass
        win.configure(bg="#111117")
        pos = getattr(self, "_float_pos", None)
        if not pos:
            try:
                pos = (win.winfo_screenwidth() - 260, 60)
            except Exception:
                pos = (60, 60)
        win.geometry(f"+{int(pos[0])}+{int(pos[1])}")

        marco = tk.Frame(win, bg="#111117", highlightbackground="#7c5cff", highlightthickness=2)
        marco.pack()
        fila = tk.Frame(marco, bg="#111117")
        fila.pack(padx=6, pady=(6, 2))

        def boton(texto, cmd, fg="#dfe2ff"):
            return tk.Button(fila, text=texto, command=cmd, bg="#1c1c25", fg=fg,
                             activebackground="#2a3150", activeforeground="#ffffff",
                             relief="flat", bd=0, font=("Segoe UI", 12, "bold"),
                             width=3, cursor="hand2")

        self._float_power_img = ("voiceicc_on" in self.ui_floating_images
                                 and "voiceicc_off" in self.ui_floating_images)
        if self._float_power_img:
            self._float_power = tk.Button(fila, command=self.vm_toggle_power,
                                          image=self.ui_floating_images["voiceicc_off"],
                                          bg="#111117", activebackground="#111117",
                                          relief="flat", bd=0, cursor="hand2")
        else:
            self._float_power = tk.Button(fila, text="⏻", command=self.vm_toggle_power,
                                          bg="#241a3d", fg="#a78bfa", activebackground="#7c3cff",
                                          activeforeground="#ffffff", relief="flat", bd=0,
                                          font=("Segoe UI", 14, "bold"), width=3, cursor="hand2")
        self._float_power.pack(side="left", padx=2)
        self._float_voice_btn = tk.Button(fila, text="🎭", command=self.toggle_voice_normal,
                                          bg="#1c1c25", fg="#dfe2ff", activebackground="#2a3150",
                                          activeforeground="#ffffff", relief="flat", bd=0,
                                          font=("Segoe UI", 12, "bold"), width=3, cursor="hand2")
        self._float_voice_btn.pack(side="left", padx=2)
        boton("🔇", lambda: (self.mute.set(not bool(self.mute.get())), self.update_engine())).pack(side="left", padx=2)
        boton("↔", self.toggle_previous_voice).pack(side="left", padx=2)
        boton("🆘", self.panic_reset, fg="#ffcf5c").pack(side="left", padx=2)
        boton("▢", self.show_window).pack(side="left", padx=2)
        boton("✕", self.toggle_float_panel, fg="#ff5c8a").pack(side="left", padx=2)

        # Segunda fila: hasta 5 voces favoritas para cambiar en un clic.
        fav_fila = tk.Frame(marco, bg="#111117")
        fav_fila.pack(padx=6, pady=(0, 2))
        favoritas = [v for v in self.favorites if v in VoiceBank.all_presets()][:5]
        if not favoritas:
            favoritas = ["Gaming limpio", "Fortnite grave", "Titán", "Robot directo", "Alien"]
            favoritas = [v for v in favoritas if v in VoiceBank.all_presets()][:5]
        for voz in favoritas:
            corta = voz.split()[0][:6]
            tk.Button(fav_fila, text=corta, command=lambda v=voz: self.apply_pro_voice(v),
                      bg="#181d2e", fg="#c7d0ff", activebackground="#2a3150",
                      activeforeground="#ffffff", relief="flat", bd=0,
                      font=("Segoe UI", 8, "bold"), cursor="hand2").pack(side="left", padx=1)

        # Fila de identidad: avatar de la voz actual + nombre.
        etiqueta = tk.Frame(marco, bg="#111117")
        etiqueta.pack(fill="x", padx=6, pady=(0, 5))
        self._float_avatar_label = tk.Label(etiqueta, bg="#111117", bd=0)
        self._float_avatar_label.pack(side="left", padx=(2, 6))
        tk.Label(etiqueta, textvariable=self.preset, bg="#111117", fg="#c7d0ff",
                 font=("Segoe UI", 9, "bold"), anchor="w").pack(side="left", fill="x", expand=True)
        self._float_update_avatar()

        def empezar(evento):
            win._arrastre = (evento.x, evento.y)

        def mover(evento):
            inicio = getattr(win, "_arrastre", None)
            if not inicio:
                return
            x = win.winfo_x() + evento.x - inicio[0]
            y = win.winfo_y() + evento.y - inicio[1]
            win.geometry(f"+{x}+{y}")
            self._float_pos = (x, y)

        for widget in (marco, fila, fav_fila, etiqueta):
            widget.bind("<Button-1>", empezar)
            widget.bind("<B1-Motion>", mover)

        self._float_refresh()

    def _float_refresh(self):
        try:
            if getattr(self, "_float_win", None) is None:
                return
            if getattr(self, "_float_power_img", False):
                if self.engine.running and bool(self.mute.get()):
                    self._float_power.configure(image=self.ui_floating_images["voiceicc_muted"])
                elif self.engine.running:
                    self._float_power.configure(image=self.ui_floating_images["voiceicc_on"])
                else:
                    self._float_power.configure(image=self.ui_floating_images["voiceicc_off"])
            elif self.engine.running:
                self._float_power.configure(bg="#123524", fg="#62ffb4")
            else:
                self._float_power.configure(bg="#241a3d", fg="#a78bfa")
            if getattr(self, "_float_voice_btn", None) is not None:
                if bool(self.effects_enabled.get()):
                    self._float_voice_btn.configure(bg="#241a3d", fg="#c7a6ff")  # modulada
                else:
                    self._float_voice_btn.configure(bg="#1c1c25", fg="#8e96b1")  # normal
        except Exception:
            pass

    def _animate_dock_waveform(self):
        """Anima la onda del dock: recorre los fotogramas cuando el motor está
        activo y no está silenciado; se queda quieta (plano) si está parado."""
        try:
            frames = getattr(self, "_dock_wave_frames", None)
            wave = getattr(self, "vm_dock_wave", None)
            if frames and wave is not None:
                activo = self.engine.running and not bool(self.mute.get())
                if activo:
                    self._dock_wave_i = (self._dock_wave_i + 1) % len(frames)
                    wave.configure(image=frames[self._dock_wave_i])
                else:
                    self._dock_wave_i = 0
                    wave.configure(image=frames[0])
        except Exception:
            pass
        try:
            self.root.after(120, self._animate_dock_waveform)
        except Exception:
            pass

    def vm_toggle_power(self):
        if self.engine.running:
            self.stop()
        else:
            self.start()
        self.vm_refresh_power()

    def vm_refresh_power(self):
        try:
            if self.engine.running:
                self.vm_power_button.configure(bg="#123524", fg="#62ffb4")
            else:
                self.vm_power_button.configure(bg="#241a3d", fg="#a78bfa")
        except Exception:
            pass

    def _img_toggle(self, parent, base, var, command):
        """Crea un interruptor con imagen (pack de UI funcional) enlazado a un
        BooleanVar. La imagen ON/OFF se intercambia al pulsar y también si la
        variable cambia desde otro sitio. Devuelve el widget Label, o None si
        no hay imágenes para ese interruptor (el llamador usa texto entonces)."""
        on_img = self.ui_toggle_images.get(f"{base}_on_wide")
        off_img = self.ui_toggle_images.get(f"{base}_off_wide")
        if on_img is None or off_img is None:
            return None
        lbl = tk.Label(parent, bg="#101016", bd=0, cursor="hand2")

        def _refrescar(*_):
            try:
                lbl.configure(image=on_img if bool(var.get()) else off_img)
            except Exception:
                pass

        def _pulsar(_evento):
            var.set(not bool(var.get()))
            _refrescar()
            if command is not None:
                try:
                    command()
                except Exception:
                    pass

        lbl.bind("<Button-1>", _pulsar)
        try:
            var.trace_add("write", _refrescar)
        except Exception:
            try:
                var.trace("w", _refrescar)
            except Exception:
                pass
        _refrescar()
        return lbl

    def _run_deferred_startup(self):
        """Carga los packs de imagen y construye los módulos ocultos en segundo
        plano, una sola vez, tras pintar la ventana. Acelera el arranque."""
        if getattr(self, "_deferred_done", False):
            return
        self._deferred_done = True
        for relative_dir, target, label in getattr(self, "_deferred_pack_folders", []):
            try:
                self.release_asset_count += self._load_release_png_folder(relative_dir, target, label)
            except Exception as exc:
                print(f"No se pudo cargar pack diferido {relative_dir}: {exc}")
        for build in getattr(self, "_deferred_tab_builds", []):
            try:
                build()
            except Exception as exc:
                print(f"No se pudo construir módulo diferido {getattr(build, '__name__', build)}: {exc}")
        # Miniaturas de voces + refresco de TODAS las rejillas que las usan
        # (favoritos, personajes, caja de voces y vista previa).
        try:
            self._load_voice_thumbnails()
            for metodo in ("refresh_favoritos_pro", "update_voice_preview",
                           "populate_personas_grid", "populate_voicebox_grid"):
                fn = getattr(self, metodo, None)
                if callable(fn):
                    try:
                        fn()
                    except Exception:
                        pass
        except Exception as exc:
            print(f"No se pudieron cargar/refrescar miniaturas de voz: {exc}")

