    def fx_designer_generate_wave_array(self, fx_type, duration=1.5, intensity=70, sample_rate=44100):
        import numpy as _np
        import math as _math
        rng = _np.random.default_rng(int(time.time()) % 2**32)
        duration = max(0.25, min(8.0, float(duration)))
        intensity = max(0.05, min(1.0, float(intensity) / 100.0))
        n = int(sample_rate * duration)
        t = _np.arange(n, dtype=_np.float32) / sample_rate
        y = _np.zeros(n, dtype=_np.float32)
        fade = _np.minimum(1.0, t / max(0.025, duration*0.05)) * _np.minimum(1.0, (duration - t) / max(0.025, duration*0.08))
        fade = _np.clip(fade, 0, 1)
        noise = rng.normal(0, 1, n).astype(_np.float32)

        def low_env(power=1.8):
            return _np.clip((1.0 - t / duration), 0, 1) ** power
        def rise_env(power=1.6):
            return _np.clip((t / duration), 0, 1) ** power

        if "whoosh" in fx_type.lower() or "subida" in fx_type.lower():
            sweep = 220 + (3600 * rise_env(1.3))
            phase = 2*_np.pi*_np.cumsum(sweep)/sample_rate
            y += 0.28*intensity*_np.sin(phase)*fade*rise_env(1.2)
            y += 0.16*intensity*noise*fade*rise_env(1.0)
        elif "boom" in fx_type.lower() or "tensión" in fx_type.lower():
            y += 0.65*intensity*_np.sin(2*_np.pi*55*t)*low_env(3.0)*fade
            y += 0.25*intensity*_np.sin(2*_np.pi*92*t)*low_env(2.5)*fade
            y += 0.08*intensity*noise*low_env(2.2)*fade
        elif "lluvia" in fx_type.lower():
            y += 0.11*intensity*noise*fade
            for _ in range(max(20, int(duration*45))):
                idx = rng.integers(0, n)
                length = rng.integers(80, 420)
                end = min(n, idx+length)
                click = _np.hanning(end-idx).astype(_np.float32) * rng.uniform(0.08, 0.22)*intensity
                y[idx:end] += click
        elif "vinilo" in fx_type.lower() or "cinta" in fx_type.lower():
            y += 0.045*intensity*noise*fade
            y += 0.08*intensity*_np.sin(2*_np.pi*0.55*t) * fade
            for _ in range(max(8, int(duration*14))):
                idx = rng.integers(0, n-20)
                length = rng.integers(10, 80)
                y[idx:idx+length] += rng.uniform(-0.45, 0.45)*intensity*_np.hanning(length)
        elif "ciudad" in fx_type.lower() or "ambiente" in fx_type.lower() or "aire" in fx_type.lower() or "estudio" in fx_type.lower():
            y += 0.055*intensity*noise*fade
            y += 0.07*intensity*_np.sin(2*_np.pi*65*t)*fade
            y += 0.025*intensity*_np.sin(2*_np.pi*330*t + 0.4*_np.sin(2*_np.pi*0.4*t))*fade
        elif "click" in fx_type.lower() or "confirmación" in fx_type.lower():
            for f, delay in [(880,0.0),(1320,0.055)]:
                env = _np.exp(-26*_np.maximum(0,t-delay)) * (t>=delay)
                y += 0.35*intensity*_np.sin(2*_np.pi*f*_np.maximum(0,t-delay))*env
        elif "radio" in fx_type.lower():
            y += 0.22*intensity*noise*fade
            y += 0.18*intensity*_np.sin(2*_np.pi*950*t)*_np.exp(-8*t)*fade
            y += 0.10*intensity*_np.sin(2*_np.pi*1800*t)*fade*(_np.sin(2*_np.pi*6*t)>0)
        elif "cuenta" in fx_type.lower():
            for k in range(3):
                delay = k * duration/4
                env = _np.exp(-18*_np.maximum(0,t-delay)) * (t>=delay)
                y += 0.30*intensity*_np.sin(2*_np.pi*(550+k*110)*_np.maximum(0,t-delay))*env
        else:
            y += 0.20*intensity*_np.sin(2*_np.pi*440*t)*fade
            y += 0.08*intensity*noise*fade

        # Pequeña cola/reverberación simple para que no suene seco.
        delay = int(sample_rate * 0.045)
        if delay < n:
            y[delay:] += 0.18 * y[:-delay]
        delay2 = int(sample_rate * 0.095)
        if delay2 < n:
            y[delay2:] += 0.10 * y[:-delay2]
        maxv = float(_np.max(_np.abs(y)) or 1.0)
        y = 0.88 * y / max(1.0, maxv)
        return y.astype(_np.float32), sample_rate

    def fx_designer_write_wav(self, path, y, sample_rate=44100):
        import wave as _wave, struct as _struct
        path = Path(path)
        with _wave.open(str(path), "w") as wf:
            wf.setnchannels(1)
            wf.setsampwidth(2)
            wf.setframerate(sample_rate)
            frames = b"".join(_struct.pack("<h", int(max(-1, min(1, float(v))) * 32767)) for v in y)
            wf.writeframes(frames)

    def fx_designer_convert_mp3(self, wav_path, mp3_path):
        try:
            subprocess.run(["ffmpeg", "-y", "-loglevel", "error", "-i", str(wav_path), "-codec:a", "libmp3lame", "-qscale:a", "4", str(mp3_path)], check=True)
            return True
        except Exception:
            return False

    def fx_designer_generate_custom(self):
        try:
            folder = self.fx_designer_folder()
            fx_type = self.fx_designer_type.get()
            duration = float(self.fx_designer_duration.get())
            intensity = float(self.fx_designer_intensity.get())
            slug = re.sub(r"[^a-zA-Z0-9]+", "_", fx_type.lower()).strip("_") or "fx"
            ts = datetime.now().strftime("%Y%m%d_%H%M%S")
            wav_path = folder / f"{slug}_{ts}.wav"
            mp3_path = folder / f"{slug}_{ts}.mp3"
            y, sr = self.fx_designer_generate_wave_array(fx_type, duration, intensity)
            self.fx_designer_write_wav(wav_path, y, sr)
            mp3_ok = self.fx_designer_convert_mp3(wav_path, mp3_path)
            self.fx_designer_status.set(self.language_text(
                f"Efecto creado: {wav_path.name}" + (" + MP3" if mp3_ok else " (WAV; MP3 requiere ffmpeg)"),
                f"Effect created: {wav_path.name}" + (" + MP3" if mp3_ok else " (WAV; MP3 needs ffmpeg)")
            ))
            self.fx_designer_refresh_preview()
            messagebox.showinfo(self.language_text("Efecto creado", "Effect created"), str(mp3_path if mp3_ok else wav_path))
        except Exception as e:
            self.fx_designer_status.set(f"Error creando efecto: {e}")

    def fx_designer_export_factory_pack(self):
        try:
            folder = self.fx_designer_folder()
            ts = datetime.now().strftime("%Y%m%d_%H%M%S")
            pack_dir = folder / f"fx_designer_factory_pack_{ts}"
            pack_dir.mkdir(parents=True, exist_ok=True)
            manifest = []
            for fx_type in self.fx_designer_types():
                for variant, mult in [("natural", 0.85), ("wide", 1.15)]:
                    dur = 1.35 if "click" in fx_type.lower() or "confirmación" in fx_type.lower() else 2.0
                    y, sr = self.fx_designer_generate_wave_array(fx_type, dur, 70*mult)
                    slug = re.sub(r"[^a-zA-Z0-9]+", "_", fx_type.lower()).strip("_")
                    wav_path = pack_dir / f"{slug}_{variant}.wav"
                    mp3_path = pack_dir / f"{slug}_{variant}.mp3"
                    self.fx_designer_write_wav(wav_path, y, sr)
                    mp3_ok = self.fx_designer_convert_mp3(wav_path, mp3_path)
                    manifest.append({"name": fx_type, "variant": variant, "wav": wav_path.name, "mp3": mp3_path.name if mp3_ok else None})
            (pack_dir / "manifest.json").write_text(json.dumps({"version": VERSION, "created_at": datetime.now().isoformat(timespec="seconds"), "items": manifest}, ensure_ascii=False, indent=2), encoding="utf-8")
            (pack_dir / "LEEME_FX_DESIGNER.txt").write_text("Pack de efectos originales generados por V1.4 Neon Voicebox UI. Incluye WAV y MP3 cuando FFmpeg está disponible.\n", encoding="utf-8")
            zip_path = folder / f"fx_designer_factory_pack_{ts}.zip"
            with zipfile.ZipFile(zip_path, "w", zipfile.ZIP_DEFLATED) as z:
                for f in pack_dir.rglob("*"):
                    z.write(f, f.relative_to(pack_dir.parent))
            self.fx_designer_status.set(self.language_text("Pack factory exportado.", "Factory pack exported."))
            messagebox.showinfo(self.language_text("Pack exportado", "Pack exported"), str(zip_path))
        except Exception as e:
            self.fx_designer_status.set(f"Error exportando pack: {e}")

