    def fx_mixer_load_wav(self, name):
        path = self.fx_mixer_audio_file(name, "wav")
        if not path.exists():
            return None, None
        with wave.open(str(path), "rb") as wf:
            rate = wf.getframerate()
            channels = wf.getnchannels()
            width = wf.getsampwidth()
            raw = wf.readframes(wf.getnframes())
        if width != 2:
            return None, None
        samples = np.frombuffer(raw, dtype=np.int16).astype(np.float32) / 32768.0
        if channels > 1:
            samples = samples.reshape(-1, channels).mean(axis=1)
        return samples, rate

    def fx_mixer_preview_selected(self):
        name = self.fx_mixer_selected_name()
        if not name:
            self.fx_mixer_status.set("Selecciona un efecto para escucharlo.")
            return
        samples, rate = self.fx_mixer_load_wav(name)
        if samples is None:
            self.fx_mixer_status.set(f"No existe el WAV de {name}.")
            return
        def _play():
            try:
                sd.play(samples, samplerate=rate, blocking=True)
            except Exception as exc:
                self.root.after(0, lambda: self.fx_mixer_status.set(f"No se pudo reproducir: {exc}"))
        threading.Thread(target=_play, daemon=True).start()
        self.fx_mixer_status.set(f"Reproduciendo preview: {name}")

    def fx_mixer_send_selected_to_soundboard(self):
        name = self.fx_mixer_selected_name()
        if not name:
            self.fx_mixer_status.set("Selecciona un efecto para enviarlo al soundboard.")
            return
        samples, _rate = self.fx_mixer_load_wav(name)
        if samples is None:
            self.fx_mixer_status.set(f"No existe el WAV de {name}.")
            return
        self.engine.add_sfx(samples)
        self.fx_mixer_status.set(f"Efecto enviado al directo: {name}")

    def fx_mixer_create_custom_mix(self):
        try:
            a = self.fx_mixer_layer_a.get()
            b = self.fx_mixer_layer_b.get()
            duration = float(self.fx_mixer_duration.get())
            volume = max(0.05, min(1.0, float(self.fx_mixer_volume.get()) / 100.0))
            out_folder = self.fx_mixer_export_folder()
            ts = datetime.now().strftime("%Y%m%d_%H%M%S")
            out_wav = out_folder / f"mix_{a}_plus_{b}_{ts}.wav"
            sample_rate = 44100
            frames = []
            fa = 180 + (sum(ord(c) for c in a) % 620)
            fb = 120 + (sum(ord(c) for c in b) % 520)
            for i in range(int(sample_rate * duration)):
                t = i / sample_rate
                env = min(1.0, t / 0.08) * min(1.0, (duration - t) / 0.18)
                drift = math.sin(2 * math.pi * 0.22 * t) * 0.015
                val = volume * env * (0.28 * math.sin(2 * math.pi * (fa + drift) * t) + 0.18 * math.sin(2 * math.pi * fb * t))
                noise = (random.random() - 0.5) * 0.012 * env
                val = max(-1, min(1, val + noise))
                frames.append(struct.pack("<h", int(val * 32767)))
            with wave.open(str(out_wav), "w") as wf:
                wf.setnchannels(1)
                wf.setsampwidth(2)
                wf.setframerate(sample_rate)
                wf.writeframes(b"".join(frames))
            # MP3 conversion if ffmpeg available
            mp3_path = out_wav.with_suffix(".mp3")
            try:
                subprocess.run(["ffmpeg", "-y", "-loglevel", "error", "-i", str(out_wav), "-codec:a", "libmp3lame", "-q:a", "4", str(mp3_path)], check=True)
                msg = f"Mix creado WAV/MP3: {out_wav.name}"
            except Exception:
                msg = f"Mix creado en WAV: {out_wav.name} (MP3 requiere FFmpeg)"
            self.fx_mixer_status.set(msg)
            messagebox.showinfo("Mix FX creado", msg)
        except Exception as e:
            self.fx_mixer_status.set(f"Error creando mix: {e}")

    def fx_mixer_refresh_list(self):
        if not hasattr(self, "fx_mixer_list"):
            return
        category = self.fx_mixer_category.get()
        names = self.fx_mixer_library().get(category, [])
        self.fx_mixer_list.delete(0, tk.END)
        for name in names:
            wav = "WAV" if self.fx_mixer_audio_file(name, "wav").exists() else "---"
            mp3 = "MP3" if self.fx_mixer_audio_file(name, "mp3").exists() else "---"
            self.fx_mixer_list.insert(tk.END, f"{name}   ·   {wav}/{mp3}")
        if names:
            self.fx_mixer_layer_a.set(names[0])
            self.fx_mixer_layer_b.set(names[min(1, len(names)-1)])
        self.fx_mixer_status.set(f"Categoría cargada: {category} · {len(names)} efectos")

