    def _visual_overhaul_update_native_widgets(self, widget):
        """Actualiza widgets Tk clásicos que no reaccionan automáticamente a ttk.Style."""
        try:
            if isinstance(widget, tk.Canvas):
                widget.configure(bg=COLORS["bg"])
            elif isinstance(widget, tk.Text):
                widget.configure(
                    bg=COLORS["panel2"],
                    fg=COLORS["text"],
                    insertbackground=COLORS["text"],
                    selectbackground=COLORS["accent"],
                    selectforeground="#ffffff",
                )
            elif isinstance(widget, tk.Listbox):
                widget.configure(
                    bg=COLORS["panel2"],
                    fg=COLORS["text"],
                    selectbackground=COLORS["accent"],
                    selectforeground="#ffffff",
                    highlightbackground=COLORS["panel2"],
                )
        except Exception:
            pass

        try:
            for child in widget.winfo_children():
                self._visual_overhaul_update_native_widgets(child)
        except Exception:
            pass

    def apply_visual_overhaul(self, theme_name=None, density=None, show_message=True):
        try:
            if theme_name:
                self.visual_overhaul_theme.set(theme_name)
            if density:
                self.visual_overhaul_density.set(density)

            selected = self.visual_overhaul_theme.get()
            palette = self.visual_overhaul_palettes().get(
                selected,
                self.visual_overhaul_palettes()["Aurora Glass"]
            )
            COLORS.update(palette)

            self.root.configure(bg=COLORS["bg"])
            style = getattr(self, "ttk_style", ttk.Style())

            button_padding = (13, 8)
            tab_padding = (11, 6)
            card_padding_note = "Cómodo"
            density_name = self.visual_overhaul_density.get()

            if density_name == "Compacto":
                button_padding = (9, 5)
                tab_padding = (9, 4)
                card_padding_note = "Compacto"
            elif density_name == "Presentación":
                button_padding = (16, 11)
                tab_padding = (15, 8)
                card_padding_note = "Presentación"

            style.configure(".", background=COLORS["bg"], foreground=COLORS["text"], fieldbackground=COLORS["panel2"])
            style.configure("TFrame", background=COLORS["bg"])
            style.configure("Card.TFrame", background=COLORS["panel"])
            style.configure("PremiumCard.TFrame", background=COLORS["panel"])
            style.configure("Hero.TFrame", background=COLORS["panel"])
            style.configure("TLabel", background=COLORS["bg"], foreground=COLORS["text"])
            style.configure("Muted.TLabel", background=COLORS["bg"], foreground=COLORS["muted"])
            style.configure("Card.TLabel", background=COLORS["panel"], foreground=COLORS["text"])
            style.configure("Hero.TLabel", background=COLORS["panel"], foreground=COLORS["text"])
            style.configure("Section.TLabel", background=COLORS["panel"], foreground=COLORS["accent2"])
            style.configure("Pill.TLabel", background=COLORS["accent"], foreground="#ffffff")
            style.configure("TButton", padding=button_padding, background=COLORS["panel2"], foreground=COLORS["text"], borderwidth=0)
            style.map("TButton", background=[("active", COLORS["panel"]), ("pressed", COLORS["accent"])], foreground=[("active", COLORS["text"])])
            style.configure("Accent.TButton", padding=button_padding, background=COLORS["accent"], foreground="#ffffff", borderwidth=0)
            style.map("Accent.TButton", background=[("active", COLORS["accent2"]), ("pressed", COLORS["accent"])])
            style.configure("Premium.TButton", padding=button_padding, background=COLORS["accent"], foreground="#ffffff", borderwidth=0)
            style.map("Premium.TButton", background=[("active", COLORS["accent2"]), ("pressed", COLORS["accent"])])
            style.configure("Ghost.TButton", padding=button_padding, background=COLORS["panel2"], foreground=COLORS["text"], borderwidth=0)
            style.configure("Danger.TButton", padding=button_padding, background=COLORS["danger"], foreground="#ffffff")
            style.configure("TCheckbutton", background=COLORS["bg"], foreground=COLORS["text"])
            style.configure("TCombobox", fieldbackground=COLORS["panel2"], background=COLORS["panel2"], foreground=COLORS["text"])
            style.configure("TEntry", fieldbackground=COLORS["panel2"], foreground=COLORS["text"])
            style.configure("TNotebook", background=COLORS["bg"], borderwidth=0)
            style.configure("TNotebook.Tab", padding=tab_padding, background=COLORS["panel2"], foreground=COLORS["muted"], font=("Segoe UI", 9, "bold"))
            style.map("TNotebook.Tab", background=[("selected", COLORS["accent"]), ("active", COLORS["panel"])], foreground=[("selected", "#ffffff"), ("active", COLORS["text"])])
            style.configure("TLabelframe", background=COLORS["bg"], foreground=COLORS["text"], bordercolor=COLORS["panel2"])
            style.configure("TLabelframe.Label", background=COLORS["bg"], foreground=COLORS["accent2"])
            style.configure("Premium.Horizontal.TProgressbar", troughcolor=COLORS["panel2"], background=COLORS["accent2"], borderwidth=0, thickness=10)

            self._visual_overhaul_update_native_widgets(self.root)
            self.visual_overhaul_status.set(
                self.language_text(
                    f"Tema aplicado: {selected} · densidad {card_padding_note}.",
                    f"Theme applied: {selected} · {card_padding_note} density."
                )
            )
            self.visual_overhaul_refresh_preview()
            try:
                self.save_config(silent=True)
            except Exception:
                pass

            if show_message:
                messagebox.showinfo(
                    self.language_text("Aspecto actualizado", "Appearance updated"),
                    self.language_text(
                        f"Se ha aplicado el tema {selected}.",
                        f"The {selected} theme has been applied."
                    )
                )
        except Exception as e:
            self.visual_overhaul_status.set(f"Error visual: {e}")

    def visual_overhaul_export_theme(self):
        try:
            folder = Path.home() / "ModuladorVozDirecto_Canciones" / "VisualThemes"
            folder.mkdir(parents=True, exist_ok=True)
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            data = {
                "version": VERSION,
                "created_at": datetime.now().isoformat(timespec="seconds"),
                "theme": self.visual_overhaul_theme.get(),
                "density": self.visual_overhaul_density.get(),
                "palette": self.visual_overhaul_palettes().get(self.visual_overhaul_theme.get(), {}),
                "language": self.app_language.get(),
            }
            json_path = folder / f"visual_theme_{timestamp}.json"
            css_path = folder / f"visual_theme_{timestamp}.css"
            json_path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
            palette = data["palette"]
            css_path.write_text(
                ":root {\n"
                + "\n".join(
                    f"  --{key.replace('_', '-')}: {value};"
                    for key, value in palette.items()
                )
                + "\n}\n",
                encoding="utf-8",
            )
            self.visual_overhaul_status.set(
                self.language_text("Tema exportado en JSON y CSS.", "Theme exported as JSON and CSS.")
            )
            messagebox.showinfo(
                self.language_text("Tema exportado", "Theme exported"),
                f"{json_path}\n{css_path}"
            )
        except Exception as e:
            self.visual_overhaul_status.set(f"Error exportando tema: {e}")

    def visual_overhaul_refresh_preview(self):
        if not hasattr(self, "visual_overhaul_preview"):
            return
        theme = self.visual_overhaul_theme.get()
        density = self.visual_overhaul_density.get()
        palette = self.visual_overhaul_palettes().get(theme, {})
        lines = [
            "VISUAL OVERHAUL PRO",
            "",
            self.language_text(f"Tema: {theme}", f"Theme: {theme}"),
            self.language_text(f"Densidad: {density}", f"Density: {density}"),
            self.language_text(f"Color principal: {palette.get('accent', '')}", f"Primary color: {palette.get('accent', '')}"),
            self.language_text(f"Color secundario: {palette.get('accent2', '')}", f"Secondary color: {palette.get('accent2', '')}"),
            "",
            self.language_text("Mejoras activas:", "Active improvements:"),
            self.language_text("- Botones premium más limpios", "- Cleaner premium buttons"),
            self.language_text("- Pestañas compactas y legibles", "- Compact, readable tabs"),
            self.language_text("- Tarjetas coherentes", "- Consistent cards"),
            self.language_text("- Textos y paneles con mayor contraste", "- Higher contrast text and panels"),
            self.language_text("- Colores aplicables a toda la app", "- App-wide theme colors"),
        ]
        self.visual_overhaul_preview.configure(state="normal")
        self.visual_overhaul_preview.delete("1.0", tk.END)
        self.visual_overhaul_preview.insert("1.0", "\n".join(lines))
        self.visual_overhaul_preview.configure(state="disabled")

