    def voice_character_group(self, character):
        text = self._normalizar(" ".join([
            character.get("name", ""),
            character.get("role_es", ""),
            character.get("age", ""),
            character.get("avatar", ""),
        ]))
        if any(k in text for k in ("nino", "nina", "infantil")):
            return "Ninos"
        if any(k in text for k in ("abuelo", "abuela", "mayor")):
            return "Mayores"
        if any(k in text for k in ("robot", "ia_", "cyborg", "sintetica")):
            return "IA"
        if any(k in text for k in ("demonio", "alien", "fantasma", "monstruo", "ninja", "angel", "fantasia", "heroe", "sombra")):
            return "Fantasia"
        if any(k in text for k in ("gaming", "hacker", "gamer")):
            return "Gaming"
        return "Humanos"

    def filtered_voice_characters(self):
        filtro = self.voice_characters_filter.get()
        characters = self.voice_characters_data()
        if filtro == "Todas":
            return characters
        return [item for item in characters if self.voice_character_group(item) == filtro]

    def select_voice_character(self, name):
        self.voice_character_selected.set(name)
        try:
            data = next((item for item in self.voice_characters_data() if item["name"] == name), None)
            preset_name = data.get("preset", name) if data else name
            self.preset.set(preset_name)
            self.apply_preset()
            self.refresh_voice_list()
            if data:
                role = data["role_es"] if self.app_language.get() == "Español" else data["role_en"]
                self.voice_characters_status.set(
                    self.language_text(
                        f"Personaje aplicado: {name} - {role} - {data['tone']}",
                        f"Character applied: {name} - {role} - {data['tone']}"
                    )
                )
            else:
                self.voice_characters_status.set(f"Personaje aplicado: {name}")
        except Exception as e:
            self.voice_characters_status.set(f"Error aplicando {name}: {e}")

    def voice_characters_export_pack(self):
        try:
            folder = Path.home() / "ModuladorVozDirecto_Canciones" / "VoiceCharacters"
            folder.mkdir(parents=True, exist_ok=True)
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            pack_folder = folder / f"voice_characters_pack_{timestamp}"
            pack_folder.mkdir(parents=True, exist_ok=True)

            data = {
                "version": VERSION,
                "created_at": datetime.now().isoformat(timespec="seconds"),
                "language": self.app_language.get(),
            "visual_overhaul_theme": self.visual_overhaul_theme.get(),
            "visual_overhaul_density": self.visual_overhaul_density.get(),
                "characters": self.voice_characters_data(),
                "note": "Todos los nombres y personajes son ficticios. No clonan personas reales.",
            }
            (pack_folder / "characters.json").write_text(
                json.dumps(data, ensure_ascii=False, indent=2),
                encoding="utf-8"
            )

            source_folder = Path(resource_path("assets/voice_characters"))
            avatar_folder = Path(resource_path("assets/avatars"))
            portraits_dir = pack_folder / "retratos"
            avatars_dir = pack_folder / "avatares"
            portraits_dir.mkdir(exist_ok=True)
            avatars_dir.mkdir(exist_ok=True)
            copied = 0
            copied_avatars = 0
            for character in data["characters"]:
                image_file = source_folder / f"{character['image']}.png"
                if image_file.exists():
                    shutil.copy2(image_file, portraits_dir / image_file.name)
                    copied += 1
                avatar_key = character.get("avatar", "")
                if avatar_key:
                    avatar_file = avatar_folder / f"avatar_{avatar_key}.png"
                    if avatar_file.exists():
                        shutil.copy2(avatar_file, avatars_dir / avatar_file.name)
                        copied_avatars += 1

            zip_path = folder / f"voice_characters_pack_{timestamp}.zip"
            with zipfile.ZipFile(zip_path, "w", zipfile.ZIP_DEFLATED) as zf:
                for file in pack_folder.rglob("*"):
                    zf.write(file, file.relative_to(pack_folder.parent))

            self.voice_characters_status.set(
                self.language_text(
                    f"Pack exportado: {copied} retratos, {copied_avatars} avatares y {len(data['characters'])} personajes.",
                    f"Pack exported: {copied} portraits, {copied_avatars} avatars and {len(data['characters'])} characters."
                )
            )
            messagebox.showinfo(
                self.language_text("Pack de personajes", "Character pack"),
                str(zip_path)
            )
        except Exception as e:
            self.voice_characters_status.set(f"Error exportando personajes: {e}")

