    def set_voice_character_filter(self, filtro):
        self.voice_characters_filter.set(filtro)
        self.populate_voice_characters_gallery()

    def populate_voice_characters_gallery(self):
        gallery = getattr(self, "voice_characters_gallery", None)
        if gallery is None:
            return
        for child in gallery.winfo_children():
            child.destroy()
        characters = self.filtered_voice_characters()
        if not characters:
            ttk.Label(gallery, text="No hay personajes en este filtro.", style="Card.TLabel").grid(row=0, column=0, padx=10, pady=10, sticky="w")
            return
        try:
            self.voice_characters_status.set(
                f"Mostrando {len(characters)} de {len(self.voice_characters_data())} personajes - filtro: {self.voice_characters_filter.get()}"
            )
        except Exception:
            pass
        for index, character in enumerate(characters):
            row = index // 4
            column = index % 4
            card = ttk.Frame(gallery, style="VMCard.TFrame", padding=8)
            card.grid(row=row, column=column, sticky="nsew", padx=5, pady=5)

            image_key = character["image"]
            neon_key = f"voice_{image_key}"
            avatar_key = character.get("avatar", "")
            if neon_key in self.neon_ui_images:
                ttk.Label(card, image=self.neon_ui_images[neon_key], style="VMCard.TLabel").pack(anchor="center")
            elif image_key in self.voice_characters_images:
                ttk.Label(
                    card,
                    image=self.voice_characters_images[image_key],
                    style="Card.TLabel"
                ).pack(anchor="center")
            elif avatar_key in self.avatar_images:
                ttk.Label(card, image=self.avatar_images[avatar_key], style="Card.TLabel").pack(anchor="center")

            ttk.Label(
                card,
                text=character["name"],
                style="Card.TLabel",
                font=("Segoe UI", 12, "bold")
            ).pack(anchor="center", pady=(4, 0))

            role = character["role_es"] if self.app_language.get() == "Español" else character["role_en"]
            ttk.Label(
                card,
                text=role,
                style="Card.TLabel",
                font=("Segoe UI", 9, "bold")
            ).pack(anchor="center")

            ttk.Label(
                card,
                text=character["tone"],
                style="Card.TLabel",
                wraplength=180,
                justify="center",
                font=("Segoe UI", 9)
            ).pack(anchor="center", pady=(2, 4))

            ttk.Button(
                card,
                text=self.language_text("Usar voz", "Use voice"),
                style="Neon.TButton",
                command=lambda name=character["name"]: self.select_voice_character(name)
            ).pack(fill="x")

            gallery.columnconfigure(column, weight=1)
            gallery.rowconfigure(row, weight=1)

