    def real_voice_fx_export_demo_wav(self):
        """Genera demos WAV cortas de efectos; los MP3 se pueden crear si el usuario instala pydub+ffmpeg."""
        try:
            folder = self.real_voice_fx_folder()
            sample_rate = 44100
            duration = 1.25
            presets = [
                ("demo_phone_real_clean.wav", 660, 0.28),
                ("demo_room_small_real.wav", 440, 0.22),
                ("demo_cinema_voice_base.wav", 220, 0.34),
                ("demo_autotune_soft_base.wav", 550, 0.24),
            ]
            created = []
            for filename, freq, amp in presets:
                path = folder / filename
                with wave.open(str(path), "w") as wf:
                    wf.setnchannels(1)
                    wf.setsampwidth(2)
                    wf.setframerate(sample_rate)
                    frames = []
                    for i in range(int(sample_rate * duration)):
                        t = i / sample_rate
                        env = min(1.0, t / 0.08) * min(1.0, (duration - t) / 0.18)
                        val = amp * env * (math.sin(2*math.pi*freq*t) + 0.35*math.sin(2*math.pi*(freq*2.01)*t))
                        frames.append(struct.pack("<h", int(max(-1, min(1, val)) * 32767)))
                    wf.writeframes(b"".join(frames))
                created.append(str(path))
            self.real_voice_fx_status.set("Demos WAV realistas exportadas. Para MP3 instala pydub + ffmpeg.")
            messagebox.showinfo("Demos creadas", "\n".join(created))
        except Exception as e:
            self.real_voice_fx_status.set(f"Error creando demos WAV: {e}")

