    def vocal_chain_slider(self, parent, label, key_or_var, mn, mx, unit):
        box = ttk.Frame(parent, style="Card.TFrame")
        box.pack(fill="x", pady=6)
        top = ttk.Frame(box, style="Card.TFrame")
        top.pack(fill="x")
        ttk.Label(top, text=label + ":", style="Card.TLabel", width=18).pack(side="left")
        value_label = ttk.Label(top, style="Card.TLabel", width=10)
        value_label.pack(side="right")
        var = self.vars[key_or_var] if isinstance(key_or_var, str) else key_or_var
        ttk.Scale(box, from_=mn, to=mx, variable=var, orient="horizontal", command=lambda _=None: self.vocal_chain_apply_manual()).pack(fill="x", pady=(3,0))
        def refresh(*_):
            value_label.config(text=f"{var.get():.0f}{unit}")
        var.trace_add("write", refresh)
        refresh()

    def vocal_chain_apply_manual(self):
        try:
            # Mapear controles "profesionales" a motor interno disponible.
            if "radio" in self.vars:
                self.vars["radio"].set(max(0, min(30, self.vocal_air.get() * 0.35 + self.vocal_presence.get() * 0.20)))
            if "bass" in self.vars:
                self.vars["bass"].set(max(0, min(45, self.vocal_warmth.get() * 0.55)))
            if "echo" in self.vars:
                self.vars["echo"].set(max(0, min(55, self.vocal_reverb_send.get() * 0.35 + self.vocal_delay_send.get() * 0.22)))
            if "vocal_focus" in self.vars:
                self.vars["vocal_focus"].set(max(self.vars["vocal_focus"].get(), min(78, self.vocal_presence.get() * 1.25)))
            if "proximity" in self.vars:
                self.vars["proximity"].set(max(self.vars["proximity"].get(), min(70, self.vocal_warmth.get() * 0.85)))
            if "fx_ducking" in self.vars and self.vocal_reverb_send.get() > 8:
                self.vars["fx_ducking"].set(max(self.vars["fx_ducking"].get(), 72))
            self.update_engine()
            self.vocal_chain_refresh_text("Ajustes aplicados al motor de voz.")
        except Exception as e:
            self.vocal_chain_status.set(f"No se pudo aplicar cadena: {e}")

    def vocal_chain_apply_preset(self, mode):
        presets = {
            "clean":   {"gate":7, "comp":34, "vol":92, "air":10, "presence":20, "warmth":12, "reverb":3,  "delay":0,  "focus":58, "proximity":12, "level":74, "duck":90, "voice":"Streaming claro V1.4", "msg":"Voz limpia V1.4 aplicada."},
            "pop":     {"gate":4, "comp":38, "vol":92, "air":24, "presence":32, "warmth":16, "reverb":20, "delay":6,  "focus":48, "proximity":12, "level":52, "duck":82, "voice":"Canto limpio moderno V1.4", "msg":"Cadena Pop moderna aplicada."},
            "trap":    {"gate":5, "comp":44, "vol":93, "air":20, "presence":28, "warmth":18, "reverb":16, "delay":12, "focus":46, "proximity":18, "level":55, "duck":86, "voice":"Neon Pop Wide", "msg":"Cadena Trap moderna con ducking aplicada."},
            "podcast": {"gate":6, "comp":36, "vol":92, "air":7,  "presence":17, "warmth":34, "reverb":2,  "delay":0,  "focus":28, "proximity":46, "level":70, "duck":92, "voice":"Podcast íntimo natural V1.4", "msg":"Cadena Podcast natural aplicada."},
            "karaoke": {"gate":4, "comp":37, "vol":92, "air":22, "presence":28, "warmth":17, "reverb":23, "delay":7,  "focus":44, "proximity":14, "level":50, "duck":80, "voice":"Canto limpio moderno V1.4", "msg":"Cadena Karaoke V1.4 aplicada."},
        }
        p = presets.get(mode, presets["clean"])

        for key in ["gate", "comp", "vol"]:
            if key in self.vars:
                self.vars[key].set(p[key])
        self.vocal_air.set(p["air"])
        self.vocal_presence.set(p["presence"])
        self.vocal_warmth.set(p["warmth"])
        self.vocal_reverb_send.set(p["reverb"])
        self.vocal_delay_send.set(p["delay"])
        for key, preset_key in [("vocal_focus", "focus"), ("proximity", "proximity"), ("smart_level", "level"), ("fx_ducking", "duck")]:
            if key in self.vars:
                self.vars[key].set(p[preset_key])

        voice = p.get("voice")
        try:
            if voice in VoiceBank.all_presets():
                self.preset.set(voice)
                self.category.set(VoiceBank.all_presets()[voice][0])
                self.apply_preset()
        except Exception:
            pass

        self.vocal_chain_apply_manual()
        self.vocal_chain_status.set(p["msg"])
        self.state.set("Estado: Cadena Vocal Pro · " + p["msg"])

    def vocal_chain_store_ab(self, slot):
        snapshot = {
            "preset": self.preset.get(),
            "category": self.category.get(),
            "values": self.current_values(),
            "air": self.vocal_air.get(),
            "presence": self.vocal_presence.get(),
            "warmth": self.vocal_warmth.get(),
            "reverb": self.vocal_reverb_send.get(),
            "delay": self.vocal_delay_send.get(),
        }
        if slot == "A":
            self.vocal_ab_a = snapshot
        else:
            self.vocal_ab_b = snapshot
        self.vocal_ab_status.set(f"Cadena {slot} guardada: {snapshot['preset']}")

    def vocal_chain_recall_ab(self, slot):
        snapshot = self.vocal_ab_a if slot == "A" else self.vocal_ab_b
        if not snapshot:
            self.vocal_ab_status.set(f"Primero guarda una cadena en {slot}.")
            return False
        self.preset.set(snapshot.get("preset", self.preset.get()))
        self.category.set(snapshot.get("category", self.category.get()))
        for key, value in snapshot.get("values", {}).items():
            if key in self.vars:
                self.vars[key].set(value)
        self.vocal_air.set(snapshot.get("air", self.vocal_air.get()))
        self.vocal_presence.set(snapshot.get("presence", self.vocal_presence.get()))
        self.vocal_warmth.set(snapshot.get("warmth", self.vocal_warmth.get()))
        self.vocal_reverb_send.set(snapshot.get("reverb", self.vocal_reverb_send.get()))
        self.vocal_delay_send.set(snapshot.get("delay", self.vocal_delay_send.get()))
        self.update_engine()
        self.vocal_chain_refresh_text(f"Cadena {slot} recuperada para comparar.")
        self.vocal_ab_active.set(slot)
        self.vocal_ab_status.set(f"Escuchando cadena {slot}: {self.preset.get()}")
        return True

    def vocal_chain_toggle_ab(self):
        target = "B" if self.vocal_ab_active.get() == "A" else "A"
        if not self.vocal_chain_recall_ab(target):
            fallback = "A" if target == "B" else "B"
            self.vocal_chain_recall_ab(fallback)

    def vocal_chain_data(self):
        data = {
            "version": VERSION,
            "voice": self.preset.get(),
            "category": self.category.get(),
            "chain": {
                "gate": self.vars["gate"].get() if "gate" in self.vars else 0,
                "compressor": self.vars["comp"].get() if "comp" in self.vars else 0,
                "air": self.vocal_air.get(),
                "presence": self.vocal_presence.get(),
                "warmth": self.vocal_warmth.get(),
                "reverb": self.vocal_reverb_send.get(),
                "delay": self.vocal_delay_send.get(),
                "vocal_focus": self.vars["vocal_focus"].get() if "vocal_focus" in self.vars else 0,
                "proximity": self.vars["proximity"].get() if "proximity" in self.vars else 0,
                "smart_level": self.vars["smart_level"].get() if "smart_level" in self.vars else 0,
                "fx_ducking": self.vars["fx_ducking"].get() if "fx_ducking" in self.vars else 0,
                "volume": self.vars["vol"].get() if "vol" in self.vars else 0,
            },
            "engine_values": {k: v.get() for k, v in self.vars.items()},
        }
        return data

    def vocal_chain_refresh_text(self, extra):
        if not hasattr(self, "vocal_chain_text"):
            return
        data = self.vocal_chain_data()
        lines = [
            "CADENA VOCAL PRO",
            "",
            f"Voz: {data['voice']}",
            f"Categoría: {data['category']}",
            "",
            "ORDEN DE CADENA",
            "1. Puerta de ruido",
            "2. Compresor",
            "3. Presencia / aire",
            "4. Calidez",
            "5. Reverb / delay",
            "6. Volumen final",
            "",
            "VALORES",
        ]
        for k, v in data["chain"].items():
            lines.append(f"- {k}: {v:.0f}")
        lines += ["", str(extra)]
        self.vocal_chain_text.configure(state="normal")
        self.vocal_chain_text.delete("1.0", tk.END)
        self.vocal_chain_text.insert("1.0", "\n".join(lines))
        self.vocal_chain_text.configure(state="disabled")

    def vocal_chain_output_folder(self):
        try:
            return self.song_output_folder()
        except Exception:
            folder = Path.home() / "ModuladorVozDirecto_Canciones"
            folder.mkdir(parents=True, exist_ok=True)
            return folder

    def vocal_chain_export_json(self):
        try:
            data = self.vocal_chain_data()
            title = "cadena_vocal"
            try:
                title = self.song_safe_name(self.song_title.get())
            except Exception:
                pass
            ts = datetime.now().strftime("%Y%m%d_%H%M%S")
            path = self.vocal_chain_output_folder() / f"{title}_cadena_vocal_{ts}.json"
            path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
            self.vocal_chain_status.set(f"Cadena exportada: {path.name}")
            messagebox.showinfo("Cadena vocal exportada", f"JSON guardado en:\n{path}")
        except Exception as e:
            self.vocal_chain_status.set(f"No se pudo exportar cadena: {e}")


