        scrollable = ttk.Frame(canvas, style="Card.TFrame")

        scrollable.bind(
            "<Configure>",
            lambda e: canvas.configure(scrollregion=canvas.bbox("all"))
        )

        canvas_window = canvas.create_window((0, 0), window=scrollable, anchor="nw")
