    def update_visualizer(self):
        if self.visualizer_canvas is None:
            return
        c = self.visualizer_canvas
        w = max(1, c.winfo_width())
        h = max(1, c.winfo_height())
        c.delete("all")

        # Fondo con rejilla
        for x in range(0, w, 60):
            c.create_line(x, 0, x, h, fill="#252a42")
        for y in range(0, h, 50):
            c.create_line(0, y, w, y, fill="#252a42")

        mic = min(1.0, self.engine.mic_level * 7)
        out = min(1.0, self.engine.out_level * 7)

        bars = 28
        gap = 6
        bw = max(6, (w - gap*(bars+1)) / bars)
        import random
        for i in range(bars):
            base = (mic*0.45 + out*0.55)
            pulse = abs(math.sin((i*0.55) + (datetime.now().timestamp()*5))) * 0.55
            val = min(1, base * (0.55 + pulse))
            bh = 18 + val * (h - 70)
            x1 = gap + i*(bw+gap)
            x2 = x1 + bw
            y1 = h - bh - 20
            y2 = h - 20
            color = "#00e5ff" if i % 3 else "#7c5cff"
            c.create_rectangle(x1, y1, x2, y2, fill=color, outline="")
            if val > 0.55:
                c.create_rectangle(x1, y1, x2, y1+5, fill="#62ffb4", outline="")

        c.create_text(24, 24, anchor="w", text="ESTUDIO DE VOZ ULTRA", fill="#f5f7ff", font=("Segoe UI", 18, "bold"))
        c.create_text(24, 54, anchor="w", text=f"Micro: {int(mic*100)}%  ·  Salida: {int(out*100)}%", fill="#aab0d6", font=("Segoe UI", 11))


    def label_for_tab_attr(self, attr):
        for name, label in self.RELEASE_TABS:
            if name == attr:
                return label
        return attr

    def open_tab_by_attr(self, attr):
        tab = getattr(self, attr, None)
        if tab is not None:
            self.select_tab(tab)

    def toggle_favorite_tab(self, attr):
        if not hasattr(self, "favorite_tabs"):
            self.favorite_tabs = []
        if attr in self.favorite_tabs:
            self.favorite_tabs = [a for a in self.favorite_tabs if a != attr]
        else:
            self.favorite_tabs.append(attr)
            self.favorite_tabs = self.favorite_tabs[:8]
        self.creator_hub_status.set("Favoritos actualizados")
        self.refresh_creator_hub_panels()
        try:
            self.save_config(silent=True)
        except Exception:
            pass

    def track_recent_tab(self, attr):
        if not attr or attr == "tab_inicio_premium":
            return
        if not hasattr(self, "recent_tabs"):
            self.recent_tabs = []
        self.recent_tabs = [a for a in self.recent_tabs if a != attr]
        self.recent_tabs.insert(0, attr)
        self.recent_tabs = self.recent_tabs[:8]
        try:
            self.refresh_creator_hub_panels()
        except Exception:
            pass

    def refresh_creator_hub_panels(self):
        if hasattr(self, "home_favorites_frame"):
            for child in self.home_favorites_frame.winfo_children():
                child.destroy()
            ttk.Label(self.home_favorites_frame, text="FAVORITOS", style="Card.TLabel", font=("Segoe UI", 10, "bold")).pack(anchor="w", pady=(0, 2))
            ttk.Label(self.home_favorites_frame, text="Tus accesos fijos para preparar la sesion mas rapido.", style="Card.TLabel", font=("Segoe UI", 8)).pack(anchor="w", pady=(0, 6))
            favs = getattr(self, "favorite_tabs", []) or ["tab_test_voz", "tab_voice_characters"]
            row = ttk.Frame(self.home_favorites_frame, style="Card.TFrame")
            row.pack(fill="x")
            for idx, attr in enumerate(favs[:6]):
                wrap = ttk.Frame(row, style="Card.TFrame")
                wrap.grid(row=idx // 3, column=idx % 3, sticky="ew", padx=4, pady=4)
                ttk.Button(wrap, text=self.label_for_tab_attr(attr), style="Accent.TButton", command=lambda a=attr: self.open_tab_by_attr(a)).pack(fill="x")
                ttk.Button(wrap, text="Quitar", style="Ghost.TButton", command=lambda a=attr: self.toggle_favorite_tab(a)).pack(fill="x", pady=(3, 0))
                row.columnconfigure(idx % 3, weight=1)
        if hasattr(self, "home_recents_frame"):
            for child in self.home_recents_frame.winfo_children():
                child.destroy()
            ttk.Label(self.home_recents_frame, text="RECIENTES", style="Card.TLabel", font=("Segoe UI", 10, "bold")).pack(anchor="w", pady=(0, 2))
            ttk.Label(self.home_recents_frame, text="Continua donde estabas o vuelve a un modulo clave.", style="Card.TLabel", font=("Segoe UI", 8)).pack(anchor="w", pady=(0, 6))
            row = ttk.Frame(self.home_recents_frame, style="Card.TFrame")
            row.pack(fill="x")
            recents = getattr(self, "recent_tabs", [])[:6]
            if not recents:
                ttk.Label(row, text="Aun no hay modulos recientes.", style="Card.TLabel").pack(anchor="w", pady=(0, 6))
                ttk.Button(row, text="Abrir test de voz", style="Accent.TButton", command=lambda: self.open_tab_by_attr("tab_test_voz")).pack(anchor="w")
            else:
                for idx, attr in enumerate(recents):
                    ttk.Button(row, text=self.label_for_tab_attr(attr), command=lambda a=attr: self.open_tab_by_attr(a)).grid(row=idx // 3, column=idx % 3, sticky="ew", padx=4, pady=4)
                    row.columnconfigure(idx % 3, weight=1)
        try:
            current_attr = None
            current_section = self.notebook.nametowidget(self.notebook.select()) if hasattr(self, "notebook") else None
            if current_section is not None and hasattr(current_section, "select") and current_section.tabs():
                current_tab_widget = current_section.nametowidget(current_section.select())
                current_attr = self._tab_attr_name(current_tab_widget)
            if current_attr:
                fav = "Sí" if current_attr in getattr(self, "favorite_tabs", []) else "No"
                self.creator_hub_status.set(f"Actual: {self.label_for_tab_attr(current_attr)} · Favorito: {fav} · Recientes: {len(getattr(self, 'recent_tabs', []))}")
        except Exception:
            pass

    def pin_current_module_to_hub(self):
        try:
            section_frame = self.notebook.nametowidget(self.notebook.select())
            current_tab_widget = section_frame.nametowidget(section_frame.select())
            attr = self._tab_attr_name(current_tab_widget)
            if attr:
                self.toggle_favorite_tab(attr)
        except Exception:
            pass

