    def apply_session_profile(self, name=None):
        name = name or self.session_profile.get()
        profile = self.premium_flow_profiles().get(name, self.premium_flow_profiles()["Streaming"])
        self.session_profile.set(name)
        self.latency.set(profile["latency"])
        try:
            self.preset.set(profile["voice"])
            self.apply_preset()
            self.refresh_voice_list()
        except Exception:
            pass
        self.last_session_summary.set(f"{name} - {profile['voice']} - {profile['latency']}")
        self.premium_flow_status.set(f"Perfil aplicado: {name}. Listo para revisar audio y directo.")
        self.update_broadcast_ready()
        try:
            self.save_config(silent=True)
        except Exception:
            pass

    def save_current_session_snapshot(self):
        summary = f"{self.session_profile.get()} - {self.preset.get()} - {self.latency.get()}"
        self.last_session_summary.set(summary)
        self.premium_flow_status.set("Sesion guardada. Puedes reanudar este ajuste despues.")
        try:
            self.save_config(silent=True)
        except Exception:
            pass

    def resume_last_session(self):
        self.apply_session_profile(self.session_profile.get())
        self.premium_flow_status.set(f"Sesion recuperada: {self.last_session_summary.get()}")

    def update_broadcast_ready(self):
        checks = []
        checks.append(bool(self.input_dev.get()))
        checks.append(bool(self.output_dev.get()))
        checks.append(bool(self.preset.get()))
        checks.append(bool(self.session_profile.get()))
        done = sum(checks)
        if done == 4:
            status = "LISTO PARA EMITIR"
        elif done >= 2:
            status = f"CASI LISTO · {done}/4"
        else:
            status = f"CONFIGURA VOICEICC · {done}/4"
        self.broadcast_ready.set(status)
        try:
            self.home_live_state.set("Directo: activo" if self.engine.running else "Directo: parado")
            audio_ready = bool(self.input_dev.get()) and bool(self.output_dev.get())
            self.home_audio_state.set("Audio: listo" if audio_ready else "Audio: elige micro y salida")
            voice_name = self.voiceicc_current_voice_name.get() or self.preset.get() or "sin elegir"
            self.home_voice_state.set(f"Voz: {voice_name}")
        except Exception:
            pass
        return done

